:root {
  --bg: #f5f7fb;
  --panel: #ffffff;
  --panel-soft: #eef3ff;
  --border: #d7deeb;
  --text: #1f2937;
  --muted: #6b7280;
  --accent: #3b82f6;
  --sidebar-width: 280px;
  --sidebar-resize-bar-width: 28px;
}

* {
  box-sizing: border-box;
}

html {
  height: 100%;
}

body {
  margin: 0;
  height: 100%;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

/* Агент / workspace: без скролла документа */
html:not(:has(#app-root.app-landing-view)),
body:not(:has(#app-root.app-landing-view)) {
  overflow: hidden;
}

/* Лендинг /: скролл всей страницы как раньше */
html:has(#app-root.app-landing-view),
body:has(#app-root.app-landing-view) {
  height: auto;
  min-height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
}

body.app-booting,
body.app-locked {
  overflow: hidden;
}

.app-connection-lost {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10100;
  padding: 10px 16px;
  border-bottom: 1px solid #fecaca;
  background: linear-gradient(180deg, #fef2f2 0%, #fff7ed 100%);
  color: #7f1d1d;
  box-shadow: 0 8px 24px rgba(127, 29, 29, 0.12);
}

.app-connection-lost.hidden {
  display: none;
}

.app-connection-lost-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(1200px, 100%);
  margin: 0 auto;
}

.app-connection-lost-icon {
  flex: 0 0 auto;
  font-size: 18px;
  line-height: 1;
  animation: app-connection-lost-pulse 1.6s ease-in-out infinite;
}

@keyframes app-connection-lost-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }

  50% {
    opacity: 0.55;
    transform: scale(0.94);
  }
}

.app-connection-lost-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1 1 auto;
}

.app-connection-lost-title {
  font-size: 14px;
  font-weight: 700;
  color: #991b1b;
}

.app-connection-lost-detail {
  font-size: 13px;
  line-height: 1.45;
  color: #9a3412;
}

.app-connection-lost-detail code {
  font-size: 12px;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid #fecaca;
}

.app-connection-lost-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.app-connection-lost-retry {
  border: 1px solid #fca5a5;
  border-radius: 999px;
  background: #fff;
  color: #991b1b;
  font-size: 13px;
  font-weight: 600;
  padding: 6px 14px;
  cursor: pointer;
}

.app-connection-lost-retry:hover {
  background: #fff1f2;
}

.app-connection-lost-retry:disabled {
  opacity: 0.65;
  cursor: wait;
}

.app-connection-lost-dismiss {
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: #9a3412;
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
}

.app-connection-lost-dismiss:hover {
  background: rgba(255, 255, 255, 0.72);
}

.app-connection-lost[data-state="offline"] {
  border-bottom-color: #fde68a;
  background: linear-gradient(180deg, #fffbeb 0%, #fff7ed 100%);
  color: #92400e;
}

.app-connection-lost[data-state="offline"] .app-connection-lost-title {
  color: #92400e;
}

.app-connection-lost[data-state="offline"] .app-connection-lost-detail {
  color: #a16207;
}

.app-lock {
  position: fixed;
  inset: 0;
  z-index: 10001;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.app-lock.hidden {
  display: none;
}

.app-lock-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 55% at 12% 8%, rgba(99, 102, 241, 0.24), transparent 60%),
    radial-gradient(ellipse 65% 50% at 88% 18%, rgba(59, 130, 246, 0.2), transparent 55%),
    linear-gradient(165deg, #0f172a 0%, #1e1b4b 52%, #0f172a 100%);
}

.app-lock-panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  width: min(400px, 100%);
}

.app-lock-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  padding: 28px 26px 22px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 18px;
  background: rgba(15, 23, 42, 0.88);
  box-shadow: 0 24px 64px rgba(2, 6, 23, 0.45);
  backdrop-filter: blur(10px);
}

.app-lock-brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-bottom: 8px;
}

.app-lock-logo {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  border-radius: 12px;
  display: block;
  box-shadow: 0 8px 24px rgba(99, 102, 241, 0.35);
}

.app-lock-title {
  margin: 0;
  font-size: 1.375rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #f8fafc;
}

.app-lock-lead {
  margin: 0 0 18px;
  text-align: center;
  font-size: 14px;
  line-height: 1.5;
  color: rgba(226, 232, 240, 0.78);
}

.app-lock-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.app-lock-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.app-lock-field.hidden {
  display: none;
}

.app-lock-label {
  font-size: 12px;
  font-weight: 600;
  color: rgba(226, 232, 240, 0.72);
}

.app-lock-input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.65);
  color: #f8fafc;
  font-size: 14px;
}

.app-lock-input:focus {
  outline: none;
  border-color: #818cf8;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.22);
}

.app-lock-error {
  margin: 0;
  font-size: 13px;
  color: #fca5a5;
}

.app-lock-error.hidden {
  display: none;
}

.app-lock-submit {
  margin-top: 4px;
  padding: 10px 14px;
  border: 0;
  border-radius: 10px;
  background: linear-gradient(135deg, #6366f1, #3b82f6);
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.app-lock-submit:hover {
  opacity: 0.94;
}

.app-lock-submit:active {
  transform: scale(0.99);
}

.app-lock-submit:disabled {
  opacity: 0.72;
  cursor: wait;
}

.app-lock-biometric-btn {
  width: 100%;
  margin-top: 14px;
  padding: 10px 14px;
  border: 1px dashed rgba(148, 163, 184, 0.35);
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.45);
  color: rgba(148, 163, 184, 0.85);
  font-size: 13px;
  font-weight: 600;
  cursor: not-allowed;
}

.app-lock-biometric-btn:disabled {
  opacity: 1;
}

.app-lock-biometric-btn.hidden {
  display: none;
}

.app-lock-auth-links {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 2px;
}

.app-lock-auth-link {
  padding: 0;
  border: 0;
  background: none;
  color: rgba(148, 163, 184, 0.92);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.4;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
  transition: color 0.15s ease;
}

.app-lock-auth-link:hover:not(:disabled) {
  color: #e2e8f0;
}

.app-lock-auth-link:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  text-decoration: none;
}

.app-lock-scanner {
  margin-top: 14px;
  padding: 14px;
  border-radius: 12px;
  border: 1px solid rgba(96, 165, 250, 0.28);
  background: rgba(30, 58, 138, 0.18);
}

.app-lock-scanner.hidden {
  display: none;
}

.app-lock-scanner-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.app-lock-scanner-title-wrap {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.app-lock-scanner-glyph {
  width: 18px;
  height: 18px;
  color: #93c5fd;
  flex: 0 0 18px;
}

.app-lock-scanner-title {
  font-size: 13px;
  color: #dbeafe;
}

.app-lock-scanner-badge {
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(147, 197, 253, 0.28);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.03em;
  color: #bfdbfe;
  white-space: nowrap;
}

.app-lock-scanner-lead {
  margin: 0 0 8px;
  font-size: 11px;
  line-height: 1.45;
  color: rgba(191, 219, 254, 0.88);
}

.app-lock-scanner-status {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  color: #e0f2fe;
}

.app-lock-scanner-progress {
  margin: 0 0 10px;
  font-size: 11px;
  color: #93c5fd;
}

.app-lock-scanner-progress.hidden {
  display: none;
}

.app-lock-scanner-action {
  width: 100%;
  padding: 11px 14px;
  border: 0;
  border-radius: 10px;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.app-lock-scanner-action:hover {
  opacity: 0.96;
}

.app-lock-scanner-action:disabled {
  opacity: 0.72;
  cursor: wait;
}

.app-lock-scanner-footnote {
  margin: 10px 0 0;
  font-size: 10px;
  line-height: 1.45;
  color: rgba(148, 163, 184, 0.88);
  text-align: center;
}

.app-lock-scanner-footnote code {
  font-size: 9px;
  color: rgba(226, 232, 240, 0.88);
}

.app-lock-scanner.is-scanning {
  animation: app-lock-scanner-pulse 0.8s ease-in-out infinite;
}

@keyframes app-lock-scanner-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.28); }
  50% { box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.14); }
}

.app-lock-bio-hint {
  margin: 14px 0 0;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid rgba(34, 197, 94, 0.28);
  background: rgba(22, 163, 74, 0.12);
  font-size: 11px;
  line-height: 1.55;
  color: rgba(226, 232, 240, 0.88);
  text-align: center;
}

.app-lock-bio-hint strong {
  display: block;
  margin-bottom: 4px;
  font-size: 12px;
  color: #bbf7d0;
}

.app-lock-bio-hint em {
  font-style: normal;
  color: #86efac;
  font-weight: 600;
}

.app-lock-bio-legend {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 8px;
  margin-top: 18px;
  padding-top: 16px;
}

.app-lock-bio-legend-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex: 1 1 0;
}

.app-lock-bio-legend-item--active {
  opacity: 1;
}

.app-lock-bio-legend-item--soon {
  opacity: 0.72;
}

.app-lock-bio-legend-item--soon .app-lock-bio-legend-icon {
  box-shadow: none;
  border: 1px dashed rgba(148, 163, 184, 0.35);
}

.app-lock-bio-legend-icon {
  width: 48px;
  height: 48px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  color: #fff;
  box-shadow: 0 8px 18px rgba(2, 6, 23, 0.22);
}

.app-lock-bio-legend-icon svg {
  width: 26px;
  height: 26px;
  display: block;
}

.app-lock-bio-legend-icon--touch {
  background: linear-gradient(145deg, #fb7185, #e11d48);
}

.app-lock-bio-legend-icon--face {
  background: linear-gradient(145deg, #4ade80, #16a34a);
}

.app-lock-bio-legend-icon--optic {
  background: linear-gradient(145deg, #fb923c, #ea580c);
}

.app-lock-bio-legend-icon--qr {
  background: linear-gradient(145deg, #38bdf8, #0284c7);
}

.app-lock-bio-legend-name {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: rgba(248, 250, 252, 0.94);
  text-align: center;
}

.app-lock-bio-legend-device {
  font-size: 9px;
  line-height: 1.25;
  color: rgba(148, 163, 184, 0.9);
  text-align: center;
}

.app-lock-footnote {
  margin: 16px 0 0;
  text-align: center;
  font-size: 12px;
  line-height: 1.45;
  color: rgba(148, 163, 184, 0.82);
}

.app-lock-version-wrap {
  display: flex;
  justify-content: center;
  margin: 0;
}

.app-lock-footnote code {
  font-size: 11px;
  color: rgba(226, 232, 240, 0.88);
}

.app-splash {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  transition: opacity 0.45s ease, visibility 0.45s ease;
}

.app-splash--hide {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.app-splash-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 55% at 12% 8%, rgba(99, 102, 241, 0.24), transparent 60%),
    radial-gradient(ellipse 65% 50% at 88% 18%, rgba(59, 130, 246, 0.2), transparent 55%),
    radial-gradient(ellipse 55% 45% at 72% 88%, rgba(167, 139, 250, 0.18), transparent 50%),
    linear-gradient(160deg, #eef2ff 0%, #f8fafc 42%, #f0f9ff 100%);
}

.app-splash-bg::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.45;
  background-image:
    linear-gradient(rgba(148, 163, 184, 0.12) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.12) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: radial-gradient(ellipse 85% 75% at 50% 45%, #000 20%, transparent 100%);
}

.app-splash-inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: min(320px, 100%);
  margin: 0 auto;
  text-align: center;
  animation: app-splash-enter 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.app-splash-graphic {
  position: relative;
  width: 96px;
  height: 80px;
  margin: 0 auto 6px;
}

.app-splash-node {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
}

.app-splash-node--root {
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}

.app-splash-node--left {
  left: 50%;
  bottom: 0;
  transform: translateX(calc(-50% - 30px));
}

.app-splash-node--right {
  left: 50%;
  bottom: 0;
  transform: translateX(calc(-50% + 30px));
}

.app-splash-node-core {
  display: block;
  border-radius: 999px;
  background: linear-gradient(145deg, #60a5fa, #6366f1);
  box-shadow:
    0 0 0 4px rgba(255, 255, 255, 0.92),
    0 8px 20px rgba(59, 130, 246, 0.28);
}

.app-splash-node--root .app-splash-node-core {
  width: 18px;
  height: 18px;
  animation: app-splash-pulse 1.6s ease-in-out infinite;
}

.app-splash-node--child .app-splash-node-core {
  width: 12px;
  height: 12px;
  opacity: 0.92;
}

.app-splash-node--left .app-splash-node-core {
  animation: app-splash-pulse 1.6s ease-in-out 0.35s infinite;
}

.app-splash-node--right .app-splash-node-core {
  animation: app-splash-pulse 1.6s ease-in-out 0.7s infinite;
}

.app-splash-branch {
  position: absolute;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(99, 102, 241, 0.15), rgba(59, 130, 246, 0.75), rgba(99, 102, 241, 0.15));
  background-size: 200% 100%;
  transform-origin: center top;
  animation: app-splash-branch-flow 1.4s ease-in-out infinite;
}

.app-splash-branch--left {
  top: 16px;
  left: 50%;
  width: 42px;
  transform: rotate(42deg);
  transform-origin: 0 50%;
}

.app-splash-branch--right {
  top: 16px;
  left: 50%;
  width: 42px;
  transform: rotate(-42deg);
  transform-origin: 0 50%;
}

.app-splash-tagline {
  margin: 10px 0 0;
  width: 100%;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  color: #6b7280;
  letter-spacing: 0.01em;
}

.app-splash-brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
}

.app-splash-icon {
  font-size: 22px;
  line-height: 1;
  animation: app-splash-icon-float 2.4s ease-in-out infinite;
}

.app-splash-title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #1e293b;
}

.app-splash-version {
  margin: 6px 0 0;
  width: 100%;
  font-size: 11px;
  font-weight: 400;
  line-height: 1.35;
  color: #94a3b8;
}

.app-splash-version .app-project-version {
  font-weight: 500;
  color: #a8b4c4;
  font-variant-numeric: tabular-nums;
}

.app-splash-track {
  width: 132px;
  height: 3px;
  margin: 10px auto 0;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.22);
  overflow: hidden;
}

.app-splash-track-bar {
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #93c5fd, #6366f1, #93c5fd);
  background-size: 200% 100%;
  animation: app-splash-track 1.1s ease-in-out infinite;
}

@keyframes app-splash-enter {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes app-splash-pulse {
  0%,
  100% {
    transform: scale(1);
    box-shadow:
      0 0 0 4px rgba(255, 255, 255, 0.92),
      0 8px 20px rgba(59, 130, 246, 0.22);
  }
  50% {
    transform: scale(1.12);
    box-shadow:
      0 0 0 4px rgba(255, 255, 255, 0.96),
      0 10px 24px rgba(99, 102, 241, 0.36);
  }
}

@keyframes app-splash-branch-flow {
  0%,
  100% {
    opacity: 0.45;
    background-position: 100% 0;
  }
  50% {
    opacity: 1;
    background-position: 0 0;
  }
}

@keyframes app-splash-icon-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-3px);
  }
}

@keyframes app-splash-track {
  0% {
    transform: translateX(-120%);
    background-position: 0 0;
  }
  100% {
    transform: translateX(280%);
    background-position: 100% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .app-splash-inner,
  .app-splash-node-core,
  .app-splash-branch,
  .app-splash-icon,
  .app-splash-track-bar {
    animation: none !important;
  }

  .app-splash {
    transition: opacity 0.2s ease, visibility 0.2s ease;
  }
}

.app {
  display: grid;
  grid-template-columns: var(--sidebar-width) var(--sidebar-resize-bar-width) 1fr;
  grid-template-rows: auto minmax(0, 1fr) auto;
  height: 100dvh;
  height: 100vh;
  min-height: 100vh;
  max-height: 100dvh;
  max-height: 100vh;
  overflow: hidden;
}

/* Скрываем полосы только в сайдбаре; home-pane и workspace — видимый thin-scroll */
.sidebar,
.sidebar * {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

.sidebar::-webkit-scrollbar,
.sidebar *::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  background: transparent !important;
}

.home-pane,
.agent-canvas-pane,
.workspace-pane,
.workspace-pane .doc-slab-content,
.workspace-pane .doc-aside-panel-scroll,
.workspace-pane .node-overview,
.workspace-pane .workspace-scroll-host,
.workspace-pane .file-content-preview,
.workspace-pane .editor-code-wrap,
.workspace-pane .editor-wysiwyg-wrap,
.workspace-pane .storage-slot-tree,
.workspace-pane .storage-slot-tree-list,
