.app-landing-hero {
  position: relative;
  overflow: hidden;
  min-height: clamp(220px, 32vh, 320px);
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse 80% 60% at 50% 120%, rgba(30, 27, 75, 0.9), transparent 70%),
    linear-gradient(180deg, #030712 0%, #0f172a 42%, #1e1b4b 100%);
}

.app-landing-sky {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, #030712 0%, #0f172a 42%, #1e1b4b 100%);
}

.app-landing-pane.is-landing-bg-light .app-landing-nebula,
.app-landing-pane.is-landing-bg-light .app-landing-stars,
.app-landing-pane.is-landing-bg-light .app-landing-meteors {
  display: none;
}

.app-landing-pane.is-landing-bg-light .app-landing-sky {
  background: linear-gradient(180deg, #f0f9ff 0%, #e0f2fe 38%, #f8fafc 100%);
}

.app-landing-nebula {
  position: absolute;
  inset: 0;
  opacity: 0.85;
  background:
    radial-gradient(ellipse 55% 45% at 18% 35%, rgba(99, 102, 241, 0.35), transparent 60%),
    radial-gradient(ellipse 45% 40% at 82% 28%, rgba(59, 130, 246, 0.28), transparent 55%),
    radial-gradient(ellipse 50% 35% at 62% 78%, rgba(167, 139, 250, 0.22), transparent 50%);
}

.app-landing-stars {
  position: absolute;
  inset: 0;
  background-repeat: repeat;
}

.app-landing-stars--far {
  background-image:
    radial-gradient(1px 1px at 20px 30px, rgba(255, 255, 255, 0.55), transparent),
    radial-gradient(1px 1px at 140px 80px, rgba(255, 255, 255, 0.35), transparent),
    radial-gradient(1px 1px at 260px 160px, rgba(255, 255, 255, 0.45), transparent),
    radial-gradient(1px 1px at 380px 40px, rgba(255, 255, 255, 0.3), transparent);
  background-size: 400px 200px;
  animation: app-landing-twinkle 8s ease-in-out infinite alternate;
}

.app-landing-stars--mid {
  background-image:
    radial-gradient(1.5px 1.5px at 60px 90px, rgba(255, 255, 255, 0.75), transparent),
    radial-gradient(1.5px 1.5px at 180px 30px, rgba(255, 255, 255, 0.5), transparent),
    radial-gradient(1px 1px at 300px 120px, rgba(255, 255, 255, 0.65), transparent),
    radial-gradient(1.5px 1.5px at 420px 70px, rgba(255, 255, 255, 0.4), transparent);
  background-size: 480px 180px;
  animation: app-landing-twinkle 5s ease-in-out infinite alternate-reverse;
}

.app-landing-stars--near {
  background-image:
    radial-gradient(2px 2px at 40px 50px, rgba(255, 255, 255, 0.9), transparent),
    radial-gradient(2px 2px at 160px 140px, rgba(255, 255, 255, 0.7), transparent),
    radial-gradient(1.5px 1.5px at 280px 60px, rgba(255, 255, 255, 0.85), transparent),
    radial-gradient(2px 2px at 360px 110px, rgba(255, 255, 255, 0.6), transparent);
  background-size: 420px 220px;
  animation: app-landing-twinkle 3.5s ease-in-out infinite alternate;
}

.app-landing-meteors {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.app-landing-meteor {
  position: absolute;
  top: 0;
  left: 0;
  width: 140px;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0), rgba(255, 255, 255, 0.95) 55%, rgba(199, 210, 254, 0.4));
  box-shadow: 0 0 8px rgba(199, 210, 254, 0.8);
  opacity: 0;
  transform: rotate(-32deg);
  animation: app-landing-meteor 7s linear infinite;
}

.app-landing-meteor:nth-child(1) {
  top: 12%;
  left: 68%;
  animation-delay: 0.5s;
  animation-duration: 5.5s;
}

.app-landing-meteor:nth-child(2) {
  top: 28%;
  left: 42%;
  animation-delay: 2.8s;
  animation-duration: 6.2s;
}

.app-landing-meteor:nth-child(3) {
  top: 8%;
  left: 22%;
  animation-delay: 5.1s;
  animation-duration: 5s;
}

.app-landing-meteor:nth-child(4) {
  top: 38%;
  left: 78%;
  animation-delay: 7.4s;
  animation-duration: 6.8s;
}

@keyframes app-landing-twinkle {
  from { opacity: 0.55; }
  to { opacity: 1; }
}

@keyframes app-landing-meteor {
  0% {
    opacity: 0;
    transform: translate3d(0, 0, 0) rotate(-32deg);
  }
  6% {
    opacity: 1;
  }
  18% {
    opacity: 0;
    transform: translate3d(-320px, 320px, 0) rotate(-32deg);
  }
  100% {
    opacity: 0;
    transform: translate3d(-320px, 320px, 0) rotate(-32deg);
  }
}

