  }
}

@keyframes app-landing-platform-packet-flow {
  0% {
    left: -8%;
    opacity: 0;
  }
  8% {
    opacity: 1;
  }
  92% {
    opacity: 1;
  }
  100% {
    left: 108%;
    opacity: 0;
  }
}

@keyframes app-landing-platform-chip-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

@keyframes app-landing-platform-core-pulse {
  0%,
  100% {
    transform: scale(1);
    box-shadow:
      0 0 28px rgba(37, 99, 235, 0.65),
      0 0 64px rgba(37, 99, 235, 0.35);
  }
  50% {
    transform: scale(1.12);
    box-shadow:
      0 0 36px rgba(37, 99, 235, 0.85),
      0 0 80px rgba(37, 99, 235, 0.45);
  }
}

@keyframes app-landing-platform-orbit-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes app-landing-platform-ring-spin {
  to {
    transform: rotate(-360deg);
  }
}

@keyframes app-landing-platform-spark-float {
  0%,
  100% {
    opacity: 0;
    transform: rotate(calc(var(--spark-i, 0) * 45deg)) translateY(-46%) scale(0.5);
  }
  35%,
  65% {
    opacity: 0.9;
  }
  50% {
    transform: rotate(calc(var(--spark-i, 0) * 45deg + 180deg)) translateY(-52%) scale(1);
  }
}

@keyframes app-landing-platform-agent-stars-twinkle {
  from {
    opacity: 0.45;
  }
  to {
    opacity: 0.9;
  }
}

@keyframes app-landing-platform-mascot-hop {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

@keyframes app-landing-platform-mascot-glow {
  0%,
  100% {
    opacity: 0.65;
    transform: translateX(-50%) scale(0.92);
  }
  50% {
    opacity: 1;
    transform: translateX(-50%) scale(1.05);
  }
}

@keyframes app-landing-platform-mascot-pulse {
  0%,
  100% {
    transform: scale(1);
    box-shadow: 0 0 12px rgba(250, 204, 21, 0.55);
  }
  50% {
    transform: scale(1.12);
    box-shadow: 0 0 18px rgba(250, 204, 21, 0.8);
  }
}

@keyframes app-landing-platform-mascot-blink {
  0%,
  44%,
  48%,
  100% {
    transform: scaleY(1);
  }
  46% {
    transform: scaleY(0.12);
  }
}

@keyframes app-landing-platform-mascot-wave-left {
  0%,
  100% {
    transform: rotate(8deg);
  }
  50% {
    transform: rotate(-14deg);
  }
}

@keyframes app-landing-platform-mascot-wave-right {
  0%,
  100% {
    transform: rotate(-8deg);
  }
  50% {
    transform: rotate(14deg);
  }
}

@media (prefers-reduced-motion: reduce) {
