.app-landing-orbit {
  position: relative;
  flex: 1;
  min-height: clamp(360px, 52vh, 640px);
  border-radius: 16px;
  overflow: hidden;
}

.app-landing-orbit-stack.has-focus-panel .app-landing-orbit {
  border: 1px solid rgba(148, 163, 184, 0.14);
  box-shadow: none;
}

.app-landing-orbit-ambience {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.35s ease;
}

.app-landing-orbit-stage > .app-landing-orbit-ambience {
  z-index: 0;
}

.app-landing-pane.is-landing-bg-light .app-landing-orbit-ambience {
  opacity: 1;
}

.app-landing-orbit-ambience-grid {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(148, 163, 184, 0.2) 1px, transparent 1px);
  background-size: 26px 26px;
  mask-image: radial-gradient(ellipse 88% 78% at var(--orbit-center-x, 50%) var(--orbit-center-y, 50%), #000 0%, transparent 74%);
  opacity: 0.5;
}

.app-landing-orbit-ambience-radar {
  position: absolute;
  left: var(--orbit-center-x, 50%);
  top: var(--orbit-center-y, 50%);
  width: 0;
  height: 0;
}

.app-landing-orbit-ambience-ring {
  position: absolute;
  left: 0;
  top: 0;
  width: 72px;
  height: 72px;
  margin: -36px 0 0 -36px;
  border-style: solid;
  border-color: rgba(59, 130, 246, 0.42);
  border-radius: 50%;
  background: transparent;
  box-shadow: 0 0 18px rgba(59, 130, 246, 0.1);
  animation: app-landing-orbit-ambience-ping 14s ease-out infinite;
}

.app-landing-orbit-ambience-ring:nth-child(2) {
  animation-delay: 2.8s;
}

.app-landing-orbit-ambience-ring:nth-child(3) {
  animation-delay: 5.6s;
}

.app-landing-orbit-ambience-ring:nth-child(4) {
  animation-delay: 8.4s;
}

.app-landing-orbit-ambience-ring:nth-child(5) {
  animation-delay: 11.2s;
}

.app-landing-orbit-ambience-sweep {
  position: absolute;
  left: 0;
  top: 0;
  width: min(140vmax, 1600px);
  height: min(140vmax, 1600px);
  margin-top: calc(min(70vmax, 800px) * -1);
  margin-left: calc(min(70vmax, 800px) * -1);
  border-radius: 50%;
  background: conic-gradient(
    from 0deg at 50% 50%,
    transparent 0deg,
    rgba(59, 130, 246, 0.14) 24deg,
    rgba(96, 165, 250, 0.05) 40deg,
    transparent 56deg
  );
  animation: app-landing-orbit-radar-sweep 16s linear infinite;
}

.app-landing-orbit-sea-waves {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 48%;
  z-index: 1;
  overflow: hidden;
  pointer-events: none;
  mask-image: linear-gradient(180deg, transparent 0%, #000 18%, #000 100%);
}

.app-landing-orbit-sea-wave {
  position: absolute;
  left: -35%;
  width: 170%;
  height: 54%;
  border-radius: 42% 58% 46% 54%;
  transform-origin: 50% 62%;
  will-change: transform, border-radius;
  overflow: hidden;
}

.app-landing-orbit-sea-wave::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 0%,
    rgba(255, 255, 255, 0.18) 42%,
    rgba(255, 255, 255, 0.42) 50%,
    rgba(255, 255, 255, 0.16) 58%,
    transparent 100%
  );
  background-size: 220% 100%;
  animation: app-landing-orbit-sea-shimmer-pass 5.5s ease-in-out infinite;
}

.app-landing-orbit-sea-wave--1 {
  bottom: -24%;
  background: rgba(186, 230, 253, 0.52);
  animation: app-landing-orbit-sea-wave-1 7.5s ease-in-out infinite;
}

.app-landing-orbit-sea-wave--1::after {
  animation-duration: 6.2s;
}

.app-landing-orbit-sea-wave--2 {
  bottom: -12%;
  background: rgba(125, 211, 252, 0.4);
  animation: app-landing-orbit-sea-wave-2 9s ease-in-out infinite;
  animation-delay: -2s;
}

.app-landing-orbit-sea-wave--2::after {
  animation-duration: 7.4s;
  animation-delay: -1.2s;
}

.app-landing-orbit-sea-wave--3 {
  bottom: 0;
  background: rgba(186, 230, 253, 0.48);
  animation: app-landing-orbit-sea-wave-3 6.5s ease-in-out infinite;
  animation-delay: -3.5s;
}

.app-landing-orbit-sea-wave--3::after {
  animation-duration: 5.8s;
  animation-delay: -2.4s;
}

.app-landing-orbit-sea-wave--4 {
  bottom: 10%;
  height: 38%;
  background: rgba(240, 249, 255, 0.78);
  animation: app-landing-orbit-sea-wave-4 8.5s ease-in-out infinite;
  animation-delay: -1.8s;
}

.app-landing-orbit-sea-wave--4::after {
  opacity: 0.75;
  animation-duration: 4.8s;
}

.app-landing-orbit-sea-foam {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 32%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0) 0%, rgba(255, 255, 255, 0.68) 100%);
  animation: app-landing-orbit-sea-foam 4.5s ease-in-out infinite;
}

.app-landing-orbit-sea-shimmer {
  position: absolute;
  left: -40%;
  right: -40%;
  bottom: 8%;
  height: 22%;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.28) 48%,
    transparent 100%
  );
  filter: blur(10px);
  animation: app-landing-orbit-sea-shimmer-sweep 9s linear infinite;
}

@keyframes app-landing-orbit-ambience-ping {
  0% {
    width: 72px;
    height: 72px;
    margin: -36px 0 0 -36px;
    border-width: 6px;
    opacity: 0.58;
  }

  55% {
    opacity: 0.2;
  }

  100% {
    width: 1280px;
    height: 1280px;
    margin: -640px 0 0 -640px;
    border-width: 1px;
    opacity: 0;
  }
}

@keyframes app-landing-orbit-radar-sweep {
  to {
    transform: rotate(360deg);
  }
}

@keyframes app-landing-orbit-sea-wave-1 {
  0%,
  100% {
    transform: translate3d(-8%, 3%, 0) rotate(-2deg) scale(1.03, 1);
    border-radius: 40% 60% 44% 56%;
  }

  33% {
    transform: translate3d(5%, -4%, 0) rotate(1.6deg) scale(1.06, 0.97);
    border-radius: 52% 48% 58% 42%;
  }

  66% {
    transform: translate3d(-4%, -1%, 0) rotate(-0.8deg) scale(1.02, 1.02);
    border-radius: 46% 54% 48% 52%;
  }
}

@keyframes app-landing-orbit-sea-wave-2 {
  0%,
  100% {
    transform: translate3d(7%, 2%, 0) rotate(1.8deg) scale(1.02, 1.01);
    border-radius: 48% 52% 42% 58%;
  }

  40% {
    transform: translate3d(-6%, -5%, 0) rotate(-1.4deg) scale(1.05, 0.98);
    border-radius: 56% 44% 54% 46%;
  }

  75% {
    transform: translate3d(3%, -2%, 0) rotate(0.6deg) scale(1.01, 1.03);
    border-radius: 44% 56% 50% 50%;
  }
}

@keyframes app-landing-orbit-sea-wave-3 {
  0%,
  100% {
    transform: translate3d(-5%, 1%, 0) rotate(-1.2deg) scale(1.01, 1);
    border-radius: 50% 50% 46% 54%;
  }

  45% {
    transform: translate3d(8%, -3%, 0) rotate(1.4deg) scale(1.04, 0.99);
    border-radius: 42% 58% 52% 48%;
  }

  80% {
    transform: translate3d(-3%, 2%, 0) rotate(-0.5deg) scale(1.02, 1.01);
    border-radius: 54% 46% 44% 56%;
  }
}

@keyframes app-landing-orbit-sea-wave-4 {
  0%,
  100% {
    transform: translate3d(6%, 0, 0) rotate(1deg) scale(1.02, 1);
    border-radius: 46% 54% 50% 50%;
  }

  50% {
    transform: translate3d(-7%, -2%, 0) rotate(-1.2deg) scale(1.05, 0.98);
    border-radius: 58% 42% 46% 54%;
  }
}

@keyframes app-landing-orbit-sea-shimmer-pass {
  0% {
    background-position: 180% 0;
  }

  100% {
    background-position: -80% 0;
  }
}

@keyframes app-landing-orbit-sea-shimmer-sweep {
  0% {
    transform: translate3d(-12%, 0, 0);
    opacity: 0.35;
  }

  50% {
    opacity: 0.75;
  }

  100% {
    transform: translate3d(12%, 0, 0);
    opacity: 0.35;
  }
}

@keyframes app-landing-orbit-sea-foam {
  0%,
  100% {
    opacity: 0.68;
    transform: translate3d(0, 0, 0);
  }

  50% {
    opacity: 0.96;
    transform: translate3d(0, -3%, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .app-landing-orbit-ambience-ring {
    animation: none;
    width: 420px;
    height: 420px;
    margin: -210px 0 0 -210px;
    border-width: 3px;
    opacity: 0.16;
  }

  .app-landing-orbit-ambience-ring:nth-child(2) {
    width: 620px;
    height: 620px;
    margin: -310px 0 0 -310px;
    border-width: 2px;
  }

  .app-landing-orbit-ambience-ring:nth-child(3) {
    width: 820px;
    height: 820px;
    margin: -410px 0 0 -410px;
    border-width: 1.5px;
  }

  .app-landing-orbit-ambience-ring:nth-child(4) {
    width: 1020px;
    height: 1020px;
    margin: -510px 0 0 -510px;
    border-width: 1px;
  }

  .app-landing-orbit-ambience-ring:nth-child(5) {
    width: 1220px;
    height: 1220px;
    margin: -610px 0 0 -610px;
    border-width: 1px;
    opacity: 0.1;
  }

  .app-landing-orbit-ambience-sweep,
  .app-landing-orbit-sea-wave,
  .app-landing-orbit-sea-wave::after,
  .app-landing-orbit-sea-foam,
  .app-landing-orbit-sea-shimmer {
    animation: none !important;
  }
}

.app-landing-orbit-links {
