  height: 100%;
  pointer-events: none;
}

.app-landing-orbit-link {
  stroke: rgba(148, 163, 184, 0.28);
  stroke-width: 0.14;
  stroke-linecap: round;
  stroke-dasharray: 0.55 0.45;
  animation:
    app-landing-orbit-link-pulse 5s ease-in-out infinite,
    app-landing-orbit-link-flow 14s linear infinite;
}

.app-landing-orbit-link.is-active {
