  filter: grayscale(0.35);
}

.app-landing-orbit-bubble {
  position: relative;
  width: var(--orbit-size, 72px);
  height: var(--orbit-size, 72px);
  flex: 0 0 auto;
  padding: 0;
  border: 3px solid rgba(148, 163, 184, 0.55);
  border-radius: 50%;
  background: rgba(15, 23, 42, 0.35);
  box-shadow:
    0 10px 28px rgba(2, 6, 23, 0.35),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  cursor: pointer;
  overflow: hidden;
  transition:
    transform 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

.app-landing-orbit-bubble.is-active {
  border-color: #facc15;
  box-shadow:
    0 0 0 4px rgba(250, 204, 21, 0.28),
    0 0 24px rgba(250, 204, 21, 0.35),
    0 12px 32px rgba(2, 6, 23, 0.4);
}

.app-landing-orbit-bubble.is-inactive {
  opacity: 0.78;
  filter: grayscale(0.25);
}

.app-landing-orbit-bubble:hover,
.app-landing-orbit-bubble:focus-visible {
  transform: scale(1.14);
  outline: none;
}

.app-landing-orbit-bubble-avatar {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  overflow: hidden;
  background: linear-gradient(145deg, #312e81, #1e3a8a);
  color: #e0e7ff;
  font-size: clamp(14px, 2.2vw, 20px);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.app-landing-orbit-bubble-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.22s ease;
}

.app-landing-orbit-bubble-avatar.is-preview-loading {
  background: #f1f5f9;
}

.app-landing-orbit-bubble-avatar.is-preview-loading img {
  opacity: 0;
}

.app-landing-orbit-bubble-avatar.is-preview-loading::before {
  content: "";
  position: absolute;
  inset: 18%;
  z-index: 1;
  border: 2px solid rgba(148, 163, 184, 0.28);
  border-top-color: #6366f1;
  border-radius: 50%;
  animation: app-landing-orbit-avatar-spin 0.72s linear infinite;
}

.app-landing-orbit-bubble-avatar.is-preview-loading::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: 50%;
  background: linear-gradient(
    110deg,
    rgba(241, 245, 249, 0.2) 0%,
    rgba(255, 255, 255, 0.72) 45%,
    rgba(241, 245, 249, 0.2) 90%
  );
  background-size: 200% 100%;
  animation: app-landing-orbit-avatar-shimmer 1.35s ease-in-out infinite;
}

.app-landing-pane.is-landing-bg-light .app-landing-orbit-bubble-avatar.is-preview-loading {
  background: #fff;
}

.app-landing-pane.is-landing-bg-light .app-landing-orbit-bubble-avatar.is-preview-loading::after {
  background: linear-gradient(
    110deg,
    rgba(226, 232, 240, 0.15) 0%,
    rgba(255, 255, 255, 0.95) 45%,
    rgba(226, 232, 240, 0.15) 90%
  );
  background-size: 200% 100%;
}

@keyframes app-landing-orbit-avatar-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes app-landing-orbit-avatar-shimmer {
  0% {
    background-position: 200% 0;
  }

  100% {
    background-position: -200% 0;
  }
}

.app-landing-orbit-bubble-emoji {
  font-size: clamp(22px, 3.2vw, 30px);
  line-height: 1;
}

.app-landing-orbit-bubble-initials {
  font-size: clamp(14px, 2.2vw, 20px);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.app-landing-orbit-bubble-label {
  display: inline-block;
  width: auto;
  max-width: calc(var(--orbit-size, 72px) + 56px);
  padding: 4px 10px;
  border: 1px solid rgba(255, 255, 255, 0.92);
  border-radius: 999px;
  background: rgba(248, 250, 252, 0.96);
  color: #334155;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
  box-shadow:
    0 4px 14px rgba(2, 6, 23, 0.22),
    inset 0 0 0 1px rgba(255, 255, 255, 0.35);
}

.app-landing-orbit-bubble.is-inactive + .app-landing-orbit-bubble-label {
  background: rgba(248, 250, 252, 0.82);
  border-color: rgba(226, 232, 240, 0.95);
  color: #64748b;
}

.app-landing-orbit-item--orchestrator {
  z-index: 12;
}

.app-landing-orbit-bubble.is-orchestrator {
  overflow: visible;
  border-color: rgba(245, 158, 11, 0.72);
  background: rgba(15, 23, 42, 0.42);
}

.app-landing-orbit-bubble.is-orchestrator.is-active {
  border-color: rgba(251, 191, 36, 0.95);
  box-shadow:
    0 0 0 5px rgba(245, 158, 11, 0.3),
    0 0 32px rgba(245, 158, 11, 0.48),
    0 12px 32px rgba(2, 6, 23, 0.42);
}

.app-landing-orbit-bubble.is-orchestrator.is-inactive {
  border-color: rgba(245, 158, 11, 0.42);
  opacity: 0.82;
}

.app-landing-orbit-orchestrator-badge {
  position: absolute;
  bottom: -6px;
  left: 50%;
  z-index: 4;
  transform: translateX(-50%);
  padding: 2px 8px;
  border: 1px solid rgba(245, 158, 11, 0.55);
  border-radius: 999px;
  background: #fef3c7;
  color: #b45309;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
  line-height: 1.2;
  text-transform: uppercase;
  white-space: nowrap;
  pointer-events: none;
  box-shadow: 0 4px 12px rgba(2, 6, 23, 0.28);
}

.app-landing-orbit-bubble.is-orchestrator .app-landing-orbit-bubble-avatar {
  overflow: hidden;
  border-radius: 50%;
}

.app-landing-orbit-bubble-label.is-orchestrator {
  border-color: rgba(245, 158, 11, 0.62);
  background: rgba(255, 251, 235, 0.96);
  color: #b45309;
}

.app-landing-orbit-bubble-attention {
  width: min(calc(var(--orbit-size, 72px) + 40px), 100%);
  pointer-events: none;
}

.app-landing-orbit-bubble-attention-track {
  height: 5px;
  box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.12);
}

.app-landing-orbit-item.is-attention-highlighted .app-landing-orbit-bubble-attention-track {
  box-shadow:
    0 0 0 1px var(--orbit-attention-color, rgba(129, 140, 248, 0.55)),
    0 0 12px color-mix(in srgb, var(--orbit-attention-color, #818cf8) 42%, transparent);
}

.app-landing-orbit-create-btn {
  position: absolute;
  right: 18px;
  bottom: 18px;
  z-index: 12;
  width: 48px;
  height: 48px;
  border: 2px dashed rgba(199, 210, 254, 0.75);
  border-radius: 50%;
  background: rgba(15, 23, 42, 0.55);
  color: #c7d2fe;
  font-size: 28px;
  font-weight: 300;
  line-height: 1;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease;
}

.app-landing-orbit-attention {
  position: absolute;
  left: 18px;
  right: 78px;
  bottom: 18px;
  z-index: 8;
  padding: 8px 10px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.72);
  box-shadow: 0 10px 28px rgba(2, 6, 23, 0.28);
  backdrop-filter: blur(10px);
}

.app-landing-orbit-attention-stack {
  display: flex;
  width: 100%;
  height: 12px;
  overflow: visible;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.18);
}

.app-landing-orbit-attention-stack-segment {
  display: block;
  height: 100%;
  min-width: 2px;
  padding: 0;
  border: 0;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    filter 0.2s ease,
    opacity 0.2s ease,
    box-shadow 0.2s ease;
}

.app-landing-orbit-attention-stack-segment.is-highlighted {
  transform: scaleY(1.35);
  filter: saturate(1.2) brightness(1.08);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.28),
    0 0 16px color-mix(in srgb, var(--orbit-attention-color, #818cf8) 55%, transparent);
  z-index: 1;
}

.app-landing-orbit-attention-stack-segment.is-dimmed {
  opacity: 0.34;
  filter: saturate(0.65);
}

.app-landing-orbit-attention-stack-segment:focus-visible {
  outline: 2px solid rgba(199, 210, 254, 0.85);
  outline-offset: 2px;
}

.app-landing-orbit-attention-track {
  height: 6px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.16);
  overflow: hidden;
}

.app-landing-orbit-attention-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.app-landing-orbit-create-btn:hover {
  border-color: #a5b4fc;
  background: rgba(30, 27, 75, 0.72);
  transform: scale(1.06);
}

.app-landing-orbit-empty {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 24px;
  text-align: center;
  color: rgba(226, 232, 240, 0.82);
  font-size: 14px;
}

/* Orbit dive — провал в базу знаний агента */
.app-landing-inner.is-orbit-dive-open {
  gap: 10px;
}

.app-landing-inner.is-orbit-dive-open .app-landing-orbit-dive {
  width: 100%;
}

.app-landing-orbit-dive.is-open {
  grid-template-rows: 1fr;
  opacity: 1;
  margin-top: 0;
  flex: 1;
  min-height: clamp(360px, 52vh, 640px);
}

.app-landing-orbit-dive.hidden:not(.is-open) {
  display: none;
}

.app-landing-orbit-dive:not(.hidden) {
  display: grid;
}

.app-landing-orbit-dive {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition:
    grid-template-rows 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.4s ease;
}

.app-landing-orbit-dive-inner {
  overflow: visible;
  min-height: 0;
  width: 100%;
  max-width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  margin: 0;
  border-radius: 16px;
  border: 1px solid rgba(96, 165, 250, 0.28);
  background: #020617;
  box-shadow:
    0 28px 80px rgba(2, 6, 23, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.app-landing-orbit-dive-toolbar {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(96, 165, 250, 0.14);
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(15, 23, 42, 0.72));
  backdrop-filter: blur(8px);
}

.app-landing-orbit-dive-back,
.app-landing-orbit-dive-open {
  border: 1px solid rgba(96, 165, 250, 0.34);
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.72);
  color: rgba(226, 232, 240, 0.94);
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  padding: 8px 14px;
  cursor: pointer;
  white-space: nowrap;
}

.app-landing-orbit-dive-open {
  border-color: rgba(250, 204, 21, 0.42);
  color: #fef9c3;
}

.app-landing-orbit-dive-toolbar-copy {
  min-width: 0;
  text-align: center;
}

.app-landing-orbit-dive-eyebrow {
  margin: 0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(147, 197, 253, 0.72);
}

.app-landing-orbit-dive-title {
  margin: 2px 0 0;
  font-size: clamp(1.05rem, 2.4vw, 1.35rem);
  font-weight: 700;
  color: rgba(248, 250, 252, 0.96);
}

.app-landing-orbit-dive-stats {
  margin: 4px 0 0;
  font-size: 11px;
  color: rgba(148, 163, 184, 0.88);
}

.app-landing-orbit-dive-stage {
  position: relative;
  flex: 1;
  min-height: clamp(320px, 48vh, 580px);
  overflow: visible;
  display: flex;
  justify-content: stretch;
  background:
    radial-gradient(ellipse 90% 45% at 50% 0%, rgba(59, 130, 246, 0.24), transparent 72%),
    radial-gradient(ellipse 55% 35% at 50% 55%, rgba(99, 102, 241, 0.12), transparent 65%),
    linear-gradient(180deg, #020617 0%, #0f172a 42%, #020617 100%);
}

.app-landing-orbit-dive-nebula,
.app-landing-orbit-dive-stars {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.app-landing-orbit-dive-nebula {
  background:
    radial-gradient(circle at 50% 8%, rgba(96, 165, 250, 0.2), transparent 30%),
    radial-gradient(circle at 50% 42%, rgba(129, 140, 248, 0.12), transparent 28%),
    radial-gradient(circle at 50% 78%, rgba(56, 189, 248, 0.1), transparent 26%);
  animation: app-landing-orbit-dive-nebula 14s ease-in-out infinite alternate;
}

.app-landing-orbit-dive-stars {
  opacity: 0.55;
  background-image:
    radial-gradient(circle, rgba(255, 255, 255, 0.95) 0.6px, transparent 0.7px),
    radial-gradient(circle, rgba(191, 219, 254, 0.75) 0.5px, transparent 0.6px);
  background-size: 120px 120px, 180px 180px;
  background-position: 0 0, 40px 60px;
}

.app-landing-orbit-dive-links {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.app-landing-orbit-dive-link {
  fill: none;
  stroke: rgba(96, 165, 250, 0.22);
  stroke-width: 1.2;
  stroke-linecap: round;
  transition: stroke 0.2s ease, opacity 0.2s ease;
}

.app-landing-orbit-dive-link.is-trunk {
  stroke: rgba(250, 204, 21, 0.48);
  stroke-width: 2;
  stroke-dasharray: none;
  filter: drop-shadow(0 0 4px rgba(250, 204, 21, 0.35));
}

.app-landing-orbit-dive-link.is-leaf {
  stroke: rgba(96, 165, 250, 0.28);
  stroke-dasharray: 3 5;
  animation: app-landing-orbit-dive-link-flow 16s linear infinite;
}

.app-landing-orbit-dive-link.is-mesh {
  stroke: rgba(129, 140, 248, 0.12);
  stroke-width: 0.8;
  stroke-dasharray: 2 8;
}

.app-landing-orbit-dive-link.is-highlighted {
  stroke: rgba(191, 219, 254, 0.82);
  stroke-width: 2.2;
  opacity: 1;
}

.app-landing-orbit-dive-link.is-dimmed {
  opacity: 0.08;
}

.app-landing-orbit-dive-canvas {
  position: relative;
  z-index: 2;
  width: 100%;
  min-height: 0;
  padding: 8px clamp(16px, 4vw, 48px) 64px;
  box-sizing: border-box;
  overflow: hidden;
}

.app-landing-orbit-dive-canvas-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.app-landing-orbit-dive-canvas-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(180deg, rgba(2, 6, 23, 0.62) 0%, rgba(15, 23, 42, 0.28) 42%, rgba(2, 6, 23, 0.68) 100%),
    radial-gradient(ellipse 80% 50% at 50% 18%, rgba(59, 130, 246, 0.12), transparent 70%);
}

.app-landing-orbit-dive-canvas-bg-slide {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center top;
  background-repeat: no-repeat;
  opacity: 0;
  animation: app-landing-orbit-dive-bg-cycle 18s ease-in-out infinite;
}

.app-landing-orbit-dive-canvas-bg-slide.is-1 {
  background-image: url("/assets/orbit-dive-bg/orbit-dive-bg-1.png");
  animation-delay: 0s;
}

.app-landing-orbit-dive-canvas-bg-slide.is-2 {
  background-image: url("/assets/orbit-dive-bg/orbit-dive-bg-2.png");
  animation-delay: 6s;
}

.app-landing-orbit-dive-canvas-bg-slide.is-3 {
  background-image: url("/assets/orbit-dive-bg/orbit-dive-bg-3.png");
  animation-delay: 12s;
}

@keyframes app-landing-orbit-dive-bg-cycle {
  0% {
    opacity: 0;
  }

  4% {
    opacity: 0.52;
  }

  28% {
    opacity: 0.52;
  }

  33.33% {
    opacity: 0;
  }

  100% {
    opacity: 0;
  }
}

.app-landing-orbit-dive-graph-node {
  position: absolute;
  left: var(--dive-x, 50%);
  top: var(--dive-y, 50%);
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  animation: app-landing-orbit-dive-node-in 0.65s ease both;
  animation-delay: calc(var(--dive-delay, 0) * 45ms);
  transition:
    opacity 0.22s ease,
    filter 0.22s ease,
    transform 0.22s ease;
  z-index: 2;
}

.app-landing-orbit-dive-graph-node--shape-tile,
.app-landing-orbit-dive-graph-node--shape-wide-tile {
  width: var(--dive-w, 108px);
  gap: 0;
}

.app-landing-orbit-dive-graph-node--root {
  width: var(--dive-size, 98px);
  border: none;
  background: transparent;
  padding: 0;
  cursor: default;
  z-index: 4;
}

.app-landing-orbit-dive-graph-node--section {
  border: none;
  background: transparent;
  padding: 0;
  cursor: default;
  z-index: 3;
}

.app-landing-orbit-dive-graph-node--topic {
  border: none;
  background: transparent;
  padding: 0;
  cursor: pointer;
}

.app-landing-orbit-dive-graph-node--shape-circle.app-landing-orbit-dive-graph-node--topic {
  width: var(--dive-size, 54px);
}

.app-landing-orbit-dive-graph-node--shape-circle.app-landing-orbit-dive-graph-node--section {
  width: var(--dive-size, 70px);
  height: var(--dive-size, 70px);
}

.app-landing-orbit-dive-node-body.is-circle {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
}

.app-landing-orbit-dive-graph-node--root .app-landing-orbit-dive-node-body.is-circle {
  width: var(--dive-size, 98px);
  height: var(--dive-size, 98px);
}

.app-landing-orbit-dive-preview-mount {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  border-radius: 999px;
  border: 2px solid rgba(147, 197, 253, 0.58);
  background:
    radial-gradient(circle at 30% 25%, rgba(255, 255, 255, 0.2), transparent 42%),
    linear-gradient(145deg, rgba(30, 58, 138, 0.92), rgba(15, 23, 42, 0.96));
  box-shadow:
    0 0 0 3px rgba(96, 165, 250, 0.12),
    0 0 24px rgba(59, 130, 246, 0.32);
  overflow: hidden;
  display: grid;
  place-items: center;
}

.app-landing-orbit-dive-graph-node--root .app-landing-orbit-dive-preview-mount {
  border-color: rgba(250, 204, 21, 0.72);
  box-shadow:
    0 0 0 5px rgba(250, 204, 21, 0.12),
    0 0 42px rgba(59, 130, 246, 0.45);
}

.app-landing-orbit-dive-node-body.is-section .app-landing-orbit-dive-preview-mount {
  width: 58%;
  height: 58%;
  border-color: rgba(129, 140, 248, 0.62);
}

.app-landing-orbit-dive-preview-mount.is-square {
  border-radius: 10px;
}

.app-landing-orbit-dive-preview-mount img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.app-landing-orbit-dive-preview-mount .app-landing-orbit-dive-graph-emoji {
  font-size: calc(var(--dive-size, 54px) * 0.4);
  line-height: 1;
}

.app-landing-orbit-dive-preview-mount .node-cover-icon--in-dive-orb {
  width: 58%;
  height: 58%;
  background-size: contain;
}

.app-landing-orbit-dive-node-label {
  position: static;
  transform: none;
  max-width: min(168px, calc(var(--dive-size, 54px) * 2.6));
  font-size: 11px;
  font-weight: 600;
  line-height: 1.25;
  text-align: center;
  color: rgba(226, 232, 240, 0.94);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  pointer-events: none;
}

.app-landing-orbit-dive-node-label--root {
  max-width: 180px;
  font-size: 12px;
  color: rgba(248, 250, 252, 0.96);
}

.app-landing-orbit-dive-node-label--section {
  color: rgba(191, 219, 254, 0.92);
}

.app-landing-orbit-dive-node-label--topic {
  max-width: 140px;
  font-size: 10px;
}

.app-landing-orbit-dive-tile {
  width: 100%;
  display: flex;
  flex-direction: column;
  border-radius: 14px;
  border: 1px solid rgba(96, 165, 250, 0.34);
  background:
    linear-gradient(180deg, rgba(30, 41, 59, 0.92), rgba(15, 23, 42, 0.96));
  box-shadow:
    0 0 0 1px rgba(147, 197, 253, 0.08),
    0 12px 28px rgba(2, 6, 23, 0.42);
  overflow: hidden;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.app-landing-orbit-dive-graph-node--section .app-landing-orbit-dive-tile {
  border-color: rgba(129, 140, 248, 0.42);
