/* Section-rails layout — ствол root/sections, темы на боковых рельсах */
.app-landing-orbit-dive-root-wrap {
  position: absolute;
  left: var(--dive-x, 50%);
  top: var(--dive-y, 6%);
  transform: translate(-50%, -50%);
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  animation: app-landing-orbit-dive-node-in 0.65s ease both;
}

.app-landing-orbit-dive-root-wrap .app-landing-orbit-dive-graph-orb {
  width: var(--dive-size, 92px);
  height: var(--dive-size, 92px);
}

.app-landing-orbit-dive-root-wrap .app-landing-orbit-dive-graph-caption--root {
  position: static;
  transform: none;
  bottom: auto;
  margin-top: 4px;
}

.app-landing-orbit-dive-section-block {
  position: absolute;
  left: 50%;
  top: var(--dive-y, 22%);
  transform: translate(-50%, -50%);
  z-index: 2;
  width: 100%;
  max-width: min(980px, 100%);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: clamp(16px, 4vw, 56px);
  animation: app-landing-orbit-dive-node-in 0.65s ease both;
  animation-delay: calc(var(--dive-delay, 0) * 45ms);
  transition: opacity 0.22s ease, filter 0.22s ease;
}

.app-landing-orbit-dive-section-block.is-dimmed {
  opacity: 0.18;
  filter: saturate(0.35) blur(0.4px);
}

.app-landing-orbit-dive-section-block.is-highlighted {
  z-index: 12;
}

.app-landing-orbit-dive-rail {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.app-landing-orbit-dive-rail.is-left {
  align-items: flex-end;
  padding-right: clamp(4px, 1.5vw, 16px);
}

.app-landing-orbit-dive-rail.is-right {
  align-items: flex-start;
  padding-left: clamp(4px, 1.5vw, 16px);
}

.app-landing-orbit-dive-section-center {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.app-landing-orbit-dive-section-center .app-landing-orbit-dive-graph-ring {
  width: var(--dive-size, 68px);
  height: var(--dive-size, 68px);
}

.app-landing-orbit-dive-section-center .app-landing-orbit-dive-graph-caption--section {
  position: static;
  transform: none;
  bottom: auto;
  margin-top: 2px;
  max-width: 130px;
  font-size: 11px;
}

.app-landing-orbit-dive-rail-topic {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  width: fit-content;
  max-width: min(240px, 100%);
  padding: 6px 14px 6px 6px;
  border-radius: 999px;
  border: 1px solid rgba(96, 165, 250, 0.28);
  background: rgba(15, 23, 42, 0.78);
  color: rgba(203, 213, 225, 0.92);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.25;
  cursor: pointer;
  text-align: left;
  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease,
    opacity 0.22s ease,
    filter 0.22s ease;
}

.app-landing-orbit-dive-rail-topic.is-dimmed {
  opacity: 0.18;
  filter: saturate(0.35) blur(0.4px);
}

.app-landing-orbit-dive-rail-topic.is-highlighted {
