  background: rgba(30, 58, 138, 0.55);
}

.app-landing-orbit-dive-rail-topic.is-active {
  border-color: rgba(250, 204, 21, 0.62);
  box-shadow: 0 0 16px rgba(250, 204, 21, 0.18);
}

.app-landing-orbit-dive-rail-topic:hover,
.app-landing-orbit-dive-rail-topic:focus-visible {
  border-color: rgba(147, 197, 253, 0.55);
  transform: translateY(-1px);
}

.app-landing-orbit-dive-rail-mini-orb {
