}

.app-landing-pane.is-landing-bg-light .app-landing-orbit-dive-stats,
.app-landing-pane.is-landing-bg-light .app-landing-orbit-dive-eyebrow {
  color: #64748b;
}

@keyframes app-landing-orbit-dive-nebula {
  from { opacity: 0.75; transform: scale(1); }
  to { opacity: 1; transform: scale(1.04); }
}

@keyframes app-landing-orbit-dive-pulse {
  0%, 100% { opacity: 0.65; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.06); }
}

@keyframes app-landing-orbit-dive-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

@keyframes app-landing-orbit-dive-node-in {
  from { opacity: 0; transform: translate(-50%, -50%) scale(0.72); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

@keyframes app-landing-orbit-dive-link-flow {
  to { stroke-dashoffset: -24; }
}

@media (max-width: 720px) {
  .app-landing-orbit-dive-section-block {
    gap: 12px;
  }

  .app-landing-orbit-dive-rail-topic {
    max-width: min(180px, 100%);
    font-size: 10px;
  }

  .app-landing-orbit-dive-toolbar {
    grid-template-columns: 1fr;
  }

  .app-landing-orbit-dive-toolbar-copy {
    order: -1;
  }

  .app-landing-orbit-dive-open,
  .app-landing-orbit-dive-back {
    width: 100%;
    text-align: center;
  }
}

@keyframes app-landing-orbit-drift {
  0%,
  100% {
    transform: translate(-50%, -50%) translate(0, 0);
  }
  25% {
    transform: translate(-50%, -50%) translate(var(--orbit-float-x, 12px), calc(var(--orbit-float-y, 14px) * -1));
  }
  50% {
    transform: translate(-50%, -50%) translate(calc(var(--orbit-float-x, 12px) * -0.65), calc(var(--orbit-float-y, 14px) * 0.75));
  }
  75% {
    transform: translate(-50%, -50%) translate(calc(var(--orbit-float-x, 12px) * 0.35), calc(var(--orbit-float-y, 14px) * -0.45));
  }
}

@keyframes app-landing-orbit-link-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 0.9;
  }
}

@keyframes app-landing-orbit-link-flow {
  to {
    stroke-dashoffset: -2;
  }
}

@keyframes app-landing-orbit-hub-pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.72;
  }
  50% {
    transform: scale(1.05);
    opacity: 1;
  }
}

@keyframes app-landing-orbit-hub-glow {
  0%,
  100% {
    opacity: 0.55;
    transform: scale(0.96);
  }
  50% {
    opacity: 0.95;
    transform: scale(1.04);
  }
}

