  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 0.15rem 0 0.25rem var(--tl-gutter);
}

.agent-timeline-era-list::before {
  content: "";
  position: absolute;
  left: calc(var(--tl-axis) - 1px);
  top: 0.35rem;
  bottom: 0.35rem;
  width: 2px;
  border-radius: 2px;
  background: linear-gradient(180deg, #0ea5e9 0%, #6366f1 55%, #a78bfa 100%);
