}

.agent-timeline-pane .agent-timeline-feed-row {
  position: relative;
  display: grid;
  grid-template-columns: 6.25rem minmax(0, 1fr);
  gap: 0.65rem 1rem;
  align-items: start;
  border: 1px solid rgba(148, 163, 184, 0.28);
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.15s ease;
}

.agent-timeline-pane .agent-timeline-feed-row::after {
  --tl-dot-r: 5px;
  content: "";
  position: absolute;
  left: calc(var(--tl-axis) - var(--tl-gutter) - var(--tl-dot-r));
  top: 50%;
  width: calc(var(--tl-dot-r) * 2);
  height: calc(var(--tl-dot-r) * 2);
  border-radius: 50%;
  background: #6366f1;
  border: 2px solid #fff;
  box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.28);
  transform: translateY(-50%);
  box-sizing: border-box;
}

