  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: #f8fafc;
}

.agent-storage-container-title {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: #1e293b;
}

.agent-storage-container-path {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.agent-storage-root-note {
  margin: 0;
  padding: 8px 14px;
  font-size: 11px;
  line-height: 1.4;
  color: #64748b;
  border-bottom: 1px solid var(--border);
  background: #fffbeb;
}

.agent-storage-root-note code {
  font-size: 10px;
}

.agent-storage-slot-list {
  display: flex;
  flex-direction: column;
}

.agent-storage-slot {
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
}

.agent-storage-slot:last-child {
  border-bottom: 0;
}

.agent-storage-slot-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  margin-bottom: 8px;
}

.agent-storage-slot-kind {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 6px;
  background: #e2e8f0;
  color: #475569;
}

.agent-storage-slot-kind.is-area {
  background: #dbeafe;
  color: #1d4ed8;
}

.agent-storage-slot-title {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: #1e293b;
}

.agent-storage-slot-path {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  word-break: break-all;
}

.agent-storage-slot-open {
  margin-left: auto;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: #475569;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  cursor: pointer;
}

.agent-storage-slot-open:hover {
  border-color: #93c5fd;
  color: #1d4ed8;
  background: #eff6ff;
}

.agent-storage-slot-missing {
  margin: 0 0 8px;
  font-size: 11px;
  color: #b45309;
}

.agent-storage-layers {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.agent-storage-layer {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-radius: 8px;
  border: 1px solid #e2e8f0;
  background: #f8fafc;
  font-size: 10px;
  font-weight: 600;
  color: #94a3b8;
}

.agent-storage-layer.is-present {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: #166534;
}

.agent-storage-layer-count {
  opacity: 0.85;
}

.agent-storage-orphans {
  padding: 10px 14px;
  font-size: 11px;
  color: #64748b;
  border-top: 1px dashed var(--border);
  background: #fafafa;
}

.agent-storage-orphans code {
  font-size: 10px;
}

.agent-vault-pane {
  --vault-bg: #0f1115;
  --vault-panel: #171a21;
  --vault-panel-2: #1f2430;
  --vault-text: #e8ecf1;
  --vault-muted: #a2acb9;
  --vault-accent: #6ea8fe;
  --vault-border: #2b3240;
  --vault-ok: #4fd18b;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  background: linear-gradient(180deg, #0d1016 0%, #121722 100%);
  color: var(--vault-text);
}

.agent-vault-head {
  margin-bottom: 12px;
}

.agent-vault-pane .agent-canvas-eyebrow {
  color: var(--vault-accent);
}

.agent-vault-pane .agent-canvas-title {
  color: var(--vault-text);
}

.agent-vault-pane .agent-canvas-lead {
  color: var(--vault-muted);
}

.agent-vault-stats {
  flex-shrink: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.agent-vault-pane .agent-workspace-stat,
.agent-vault-pane .agent-vault-stat {
  border: 1px solid var(--vault-border);
  background: var(--vault-panel);
  color: var(--vault-muted);
}

.agent-vault-pane .agent-workspace-stat strong,
.agent-vault-pane .agent-vault-stat strong {
  color: var(--vault-text);
}

.agent-vault-toolbar {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(280px, auto);
  gap: 14px 18px;
  align-items: start;
  margin: 0 0 16px;
  padding: 0 4px;
  box-sizing: border-box;
}

.agent-vault-search-wrap {
  min-width: 0;
}

.agent-vault-search {
  width: 100%;
  background: var(--vault-panel);
  border: 1px solid var(--vault-border);
  border-radius: 10px;
  color: var(--vault-text);
  padding: 12px 14px;
  font-size: 14px;
  outline: none;
}

.agent-vault-search::placeholder {
  color: #7b8798;
}

.agent-vault-search:focus {
  border-color: rgba(110, 168, 254, 0.55);
  box-shadow: 0 0 0 3px rgba(110, 168, 254, 0.12);
}

.agent-vault-filters {
  display: grid;
  grid-template-columns: repeat(2, minmax(140px, 1fr));
  gap: 10px 12px;
  min-width: 0;
  align-self: end;
}

.agent-vault-select {
  width: 100%;
  min-width: 0;
  background: var(--vault-panel);
  border: 1px solid var(--vault-border);
  border-radius: 10px;
  color: var(--vault-muted);
  padding: 10px 12px;
  font-size: 13px;
  outline: none;
  cursor: not-allowed;
  opacity: 0.72;
}

.agent-vault-select:disabled {
  color: var(--vault-muted);
}

.agent-vault-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 12px;
  align-content: start;
  width: 100%;
  padding: 0 4px 48px;
  box-sizing: border-box;
}

.agent-vault-empty {
  margin: 8px 4px 0;
  color: var(--vault-muted);
  border: 1px dashed var(--vault-border);
  border-radius: 12px;
  padding: 16px;
  text-align: center;
}

.agent-vault-card {
  position: relative;
}

.agent-vault-kind {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 2;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: 1px solid transparent;
  pointer-events: none;
}

.agent-vault-kind.is-folder {
  background: rgba(250, 204, 21, 0.18);
  color: #fde68a;
  border-color: rgba(250, 204, 21, 0.35);
}

.agent-vault-kind.is-file {
  background: rgba(156, 163, 175, 0.16);
  color: #d1d5db;
  border-color: rgba(156, 163, 175, 0.35);
}

.agent-vault-pane .menu-card--gallery {
  min-height: 196px;
  border-color: var(--vault-border);
  background: var(--vault-panel);
  box-shadow: none;
}

.agent-vault-pane .menu-card--gallery:hover,
.agent-vault-pane .menu-card--gallery:focus-within,
.agent-vault-pane .menu-card--gallery.active {
  border-color: #3b4b65;
  background: var(--vault-panel-2);
  transform: translateY(-2px);
}

.agent-vault-pane .menu-card--gallery .menu-card-foot {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: auto;
  background: var(--vault-panel-2);
  border-top: 1px solid var(--vault-border);
}

.agent-vault-pane .menu-card--gallery .menu-card-title {
  color: var(--vault-text);
}

.agent-vault-pane .menu-card--gallery .menu-card-cover {
  background: #121722;
}

.agent-vault-card-foot-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 6px;
  min-width: 0;
}

.agent-vault-card-meta {
  min-width: 0;
  flex: 1 1 auto;
  font-size: 10px;
  line-height: 1.35;
  color: var(--vault-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-vault-card-category {
  display: inline-flex;
  flex: 0 0 auto;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--vault-ok);
  background: rgba(79, 209, 139, 0.1);
  border: 1px solid rgba(79, 209, 139, 0.22);
}

.agent-vault-card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.agent-vault-card-tag {
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(110, 168, 254, 0.12);
  color: #9ec5fe;
  font-size: 10px;
  line-height: 1.3;
}

@media (max-width: 960px) {
  .agent-vault-toolbar {
    grid-template-columns: 1fr;
  }

  .agent-canvas-head {
    flex-direction: column;
    align-items: stretch;
  }

  .agent-canvas-head-aside,
  .agent-workspace-stats {
    justify-content: flex-start;
  }
}

.agent-canvas-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  max-width: none;
  margin: 0 0 12px;
  padding: 0 4px;
  flex-shrink: 0;
  box-sizing: border-box;
}

.agent-canvas-head--compact {
  margin-bottom: 12px;
}

.agent-canvas-head-copy {
  min-width: 0;
  flex: 1 1 auto;
}

.agent-canvas-head-aside {
  flex-shrink: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 10px;
  justify-content: flex-end;
  align-items: flex-start;
}

.agent-workspace-stats {
  flex-shrink: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  align-items: center;
}

/* ── Unified workspace tool panes (Git, Реестр, Large files, Broken links) ── */

.agent-tool-pane {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  /* scroll stays on .agent-canvas-pane — do not override overflow here */
}

.agent-tool-head {
  margin-bottom: 10px;
}

.agent-tool-toolbar {
  padding: 0 4px 10px;
}

.agent-tool-info {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin: 0 4px 14px;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--panel-border, #cbd5e1) 65%, transparent);
  background: color-mix(in srgb, var(--panel-border, #cbd5e1) 12%, var(--panel-bg, #fff));
}

.agent-tool-info-copy {
  flex: 1 1 280px;
  min-width: 0;
}

.agent-tool-info-title {
  margin: 0 0 6px;
  font-size: 1rem;
  font-weight: 650;
  color: var(--text, #0f172a);
}

.agent-tool-info-desc {
  margin: 0;
  font-size: 0.88rem;
  line-height: 1.45;
  color: var(--text-muted, #64748b);
}

.agent-tool-info-mcp {
  margin: 6px 0 0;
  font-size: 0.78rem;
  line-height: 1.35;
  color: var(--muted, #94a3b8);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.agent-tool-body {
  width: 100%;
  margin: 0;
  padding: 0 4px 48px;
  box-sizing: border-box;
  overflow: visible;
  flex: 0 0 auto;
  min-height: 0;
}

.agent-tool-shell {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.agent-tool-loading,
.agent-tool-empty,
.agent-large-files-empty,
.agent-broken-links-empty,
.agent-git-empty,
.agent-runtime-registry-empty {
  margin: 0;
  padding: 8px 4px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--muted, #64748b);
}

.agent-tool-empty.is-alert,
.agent-large-files-empty.is-alert,
.agent-broken-links-empty.is-alert,
.agent-git-empty.is-alert,
.agent-runtime-registry-empty.is-alert {
  color: #dc2626;
}

.agent-tool-empty-card,
.agent-runtime-registry-empty-card,
.agent-large-files-empty-state,
.agent-broken-links-empty-state,
.agent-git-empty-state {
  margin: 4px;
  padding: 20px 22px;
  border-radius: 12px;
  border: 1px dashed color-mix(in srgb, var(--panel-border, #cbd5e1) 80%, transparent);
  background: color-mix(in srgb, var(--panel-bg, #fff) 96%, transparent);
}

.agent-tool-empty-title,
.agent-runtime-registry-empty-title,
.agent-large-files-empty-title,
.agent-broken-links-empty-title,
.agent-git-empty-title {
  margin: 0 0 8px;
  font-size: 1rem;
  font-weight: 650;
  color: var(--text, #0f172a);
}

.agent-tool-empty-text,
.agent-runtime-registry-empty-text,
.agent-large-files-empty-text,
.agent-broken-links-empty-text,
.agent-git-empty-text {
  margin: 0;
  font-size: 0.9rem;
  line-height: 1.5;
  color: var(--text-muted, #64748b);
}

.agent-tool-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

@media (max-width: 720px) {
  .agent-tool-info {
    flex-direction: column;
  }

  .agent-workspace-stats {
    justify-content: flex-start;
  }
}

.agent-workspace-stat,
.agent-map3-stat,
.agent-map2-stat,
.agent-table-stat,
.agent-timeline-stat,
.agent-timeline-axis-stat,
.agent-timeline-vertical-stat,
.agent-storage-stat,
.agent-vault-stat,
.agent-git-stat-chip,
.agent-large-files-stat-chip,
.agent-broken-links-stat-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(255, 255, 255, 0.88);
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  white-space: nowrap;
}

.agent-workspace-stat strong,
.agent-map3-stat strong,
.agent-map2-stat strong,
.agent-table-stat strong,
.agent-timeline-stat strong,
.agent-timeline-axis-stat strong,
.agent-timeline-vertical-stat strong,
.agent-storage-stat strong,
.agent-vault-stat strong,
.agent-git-stat-chip strong,
.agent-large-files-stat-chip strong,
.agent-broken-links-stat-chip strong {
  color: #0f172a;
  font-weight: 700;
}

.agent-workspace-stat--ok,
.agent-map3-stat--ok,
.agent-git-stat-chip.is-clean {
  color: #047857;
  border-color: rgba(52, 211, 153, 0.45);
  background: rgba(240, 253, 244, 0.95);
}

.agent-workspace-stat--soft,
.agent-map2-stat--soft {
  color: #7c3aed;
  border-color: rgba(167, 139, 250, 0.45);
  background: rgba(245, 243, 255, 0.9);
}

.agent-workspace-stat--warn,
.agent-git-stat-chip.is-dirty,
.agent-large-files-stat-chip.is-total,
.agent-broken-links-stat-chip.is-total {
  color: #c2410c;
  border-color: rgba(251, 146, 60, 0.45);
  background: rgba(255, 247, 237, 0.95);
}

.agent-workspace-refresh-btn,
.agent-timeline-refresh-btn,
.agent-git-refresh-btn,
.agent-large-files-refresh-btn,
.agent-broken-links-refresh-btn {
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(255, 255, 255, 0.88);
  color: #4338ca;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    opacity 0.15s ease;
}

.agent-workspace-refresh-btn:hover:not(:disabled),
.agent-timeline-refresh-btn:hover:not(:disabled),
.agent-git-refresh-btn:hover:not(:disabled),
.agent-large-files-refresh-btn:hover:not(:disabled),
.agent-broken-links-refresh-btn:hover:not(:disabled) {
  background: rgba(99, 102, 241, 0.08);
  border-color: rgba(99, 102, 241, 0.45);
}

.agent-workspace-refresh-btn:disabled,
.agent-timeline-refresh-btn:disabled {
  opacity: 0.55;
  cursor: wait;
}

.agent-canvas-eyebrow {
  margin: 0 0 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #6366f1;
}

.agent-canvas-title {
  margin: 0;
  font-size: clamp(1.35rem, 2.5vw, 1.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #0f172a;
}

.agent-canvas-lead {
  margin: 8px 0 0;
  max-width: 720px;
  font-size: 13px;
  line-height: 1.55;
  color: #64748b;
}

.agent-canvas-lead code {
  font-size: 12px;
}

.agent-schema-content {
  width: 100%;
  margin: 0;
  padding: 0 4px 28px;
  flex: 1;
  min-height: 0;
  box-sizing: border-box;
}

.agent-schema-tree {
  border: 1px solid var(--border);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.88);
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.05);
  padding: 16px 18px 18px;
}

.agent-schema-branch-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.agent-schema-branch-list--root {
  padding-left: 2px;
}

.agent-schema-branch-list:not(.agent-schema-branch-list--root) {
  position: relative;
  margin: 2px 0 6px 12px;
  padding-left: 20px;
}

.agent-schema-branch-list:not(.agent-schema-branch-list--root)::before {
  content: "";
  position: absolute;
  left: 0;
  top: 17px;
  bottom: 17px;
  width: 2px;
  border-radius: 2px;
  background: linear-gradient(180deg, #b8c5d4 0%, #cbd5e1 50%, #b8c5d4 100%);
  pointer-events: none;
}

.agent-schema-branch-list:not(.agent-schema-branch-list--root):has(> :only-child)::before {
  display: none;
}

.agent-schema-item {
  position: relative;
  list-style: none;
}

.agent-schema-branch-list:not(.agent-schema-branch-list--root) > .agent-schema-item::before {
  content: "";
  position: absolute;
  left: -20px;
  top: 17px;
  width: 16px;
  border-top: 2px solid #cbd5e1;
  pointer-events: none;
}

.agent-schema-branch-list:not(.agent-schema-branch-list--root) > .agent-schema-item::after {
  content: "";
  position: absolute;
  left: -25px;
  top: 13px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid #94a3b8;
  box-sizing: border-box;
  pointer-events: none;
  z-index: 1;
  transition: border-color 0.15s ease, background-color 0.15s ease;
}

.agent-schema-branch-list:not(.agent-schema-branch-list--root) > .agent-schema-item.is-area::after {
  border-color: #ca8a04;
  background: #fef9c3;
}

.agent-schema-branch-list:not(.agent-schema-branch-list--root) > .agent-schema-item.is-topic::after {
  border-color: #3b82f6;
  background: #eff6ff;
}

.agent-schema-item:hover::before,
.agent-schema-item:has(.agent-schema-node:focus-visible)::before {
  border-top-color: #7c93a8;
}

.agent-schema-item:hover::after,
.agent-schema-item:has(.agent-schema-node:focus-visible)::after {
  border-color: #64748b;
  background: #fff;
}

.agent-schema-item.is-area:hover::after,
.agent-schema-item.is-area:has(.agent-schema-node:focus-visible)::after {
  border-color: #a16207;
  background: #fef9c3;
}

.agent-schema-item.is-topic:hover::after,
.agent-schema-item.is-topic:has(.agent-schema-node:focus-visible)::after {
  border-color: #2563eb;
  background: #eff6ff;
}

.agent-schema-node {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  text-align: left;
  padding: 7px 10px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.agent-schema-node:hover,
.agent-schema-node:focus-visible {
  background: #eff6ff;
  color: #1e3a8a;
  outline: none;
}

.agent-schema-node.is-folder {
  font-weight: 600;
}

.agent-schema-node-kind {
  flex-shrink: 0;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.agent-schema-node.is-area .agent-schema-node-kind {
  background: rgba(250, 204, 21, 0.18);
  color: #a16207;
}

.agent-schema-node.is-topic .agent-schema-node-kind {
  background: rgba(59, 130, 246, 0.12);
  color: #1d4ed8;
}

.agent-schema-node-label {
  flex: 1;
