    radial-gradient(ellipse 40% 35% at 18% 78%, rgba(99, 102, 241, 0.12), transparent 55%),
    radial-gradient(ellipse 35% 30% at 82% 22%, rgba(167, 139, 250, 0.1), transparent 50%),
    linear-gradient(165deg, #0f172a 0%, #111827 45%, #0b1220 100%);
  box-shadow:
    inset 0 0 0 1px rgba(148, 163, 184, 0.12),
    0 20px 50px rgba(2, 6, 23, 0.35);
}

.agent-map-links {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

.agent-map-link {
  stroke: rgba(148, 163, 184, 0.45);
  stroke-width: 1.5;
  stroke-dasharray: 6 5;
}

.agent-map-zones {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(140px, 180px) minmax(0, 1fr);
  grid-template-rows: auto minmax(120px, 1fr) auto;
  grid-template-areas:
    "zone-core zone-memory zone-projects"
    ". . ."
    "zone-registry . zone-nodes";
  gap: 14px 16px;
  min-height: inherit;
  padding: 18px;
  box-sizing: border-box;
}

.agent-map-zone {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.72);
  backdrop-filter: blur(8px);
  box-shadow: 0 8px 24px rgba(2, 6, 23, 0.35);
  overflow: hidden;
}

.agent-map-zone--core { grid-area: zone-core; align-self: start; }
.agent-map-zone--memory { grid-area: zone-memory; align-self: start; }
.agent-map-zone--projects { grid-area: zone-projects; align-self: start; }
.agent-map-zone--registry { grid-area: zone-registry; align-self: end; }
.agent-map-zone--nodes { grid-area: zone-nodes; align-self: end; }

.agent-map-zone-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.14);
  background: rgba(30, 41, 59, 0.55);
}

.agent-map-zone-icon {
  font-size: 14px;
  line-height: 1;
}

