  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #cbd5e1;
}

.agent-map-zone-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px;
  max-height: 180px;
  overflow: auto;
}

.agent-map-tile {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 100%;
  padding: 7px 8px;
  border: 1px solid rgba(100, 116, 139, 0.28);
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.85);
  color: #e2e8f0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease;
}

.agent-map-tile:hover,
.agent-map-tile:focus-visible {
  border-color: rgba(96, 165, 250, 0.65);
  background: rgba(30, 58, 138, 0.35);
  outline: none;
  transform: translateY(-1px);
}

.agent-map-tile.is-active {
