  background: rgba(6, 78, 59, 0.28);
}

.agent-map-tile-label {
  font-size: 12px;
  font-weight: 600;
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-map-tile-sub {
  font-size: 10px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  color: #94a3b8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-map-zone-empty {
  padding: 10px 8px;
  font-size: 11px;
  color: #64748b;
}

.agent-map-hub {
  position: absolute;
  left: 50%;
  top: 54%;
  z-index: 3;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 148px;
  padding: 14px 12px;
  border-radius: 999px;
  border: 1px solid rgba(125, 211, 252, 0.35);
  background: radial-gradient(circle at 50% 30%, rgba(56, 189, 248, 0.25), rgba(15, 23, 42, 0.92) 65%);
  box-shadow:
    0 0 40px rgba(56, 189, 248, 0.18),
    0 12px 32px rgba(2, 6, 23, 0.45);
  pointer-events: none;
}

.agent-map-hub-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 26px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(148, 163, 184, 0.25);
  overflow: hidden;
}

.agent-map-hub-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.agent-map-hub-title {
  font-size: 13px;
  font-weight: 700;
  color: #f8fafc;
  text-align: center;
  line-height: 1.25;
}

.agent-map-hub-sub {
  font-size: 10px;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

@media (max-width: 900px) {
  .agent-map-zones {
    grid-template-columns: 1fr;
    grid-template-areas:
      "zone-core"
      "zone-memory"
      "zone-projects"
      "zone-registry"
      "zone-nodes";
  }

  .agent-map-hub {
    display: none;
  }

  .agent-map-links {
    display: none;
  }
}

