.sidebar-shell {
  grid-column: 1;
  grid-row: 2 / 3;
  position: relative;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.sidebar-shell > .scroll-top-btn--docked {
  position: absolute;
  right: calc(14px + var(--scroll-top-shift-x, 0px));
  bottom: calc(14px + var(--scroll-top-shift-y, 0px));
  z-index: 26;
  margin: 0;
}

.sidebar {
  grid-column: auto;
  grid-row: auto;
  flex: 1 1 auto;
  min-height: 0;
  border-right: 1px solid var(--border);
  background: var(--panel);
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 0;
  position: relative;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  box-sizing: border-box;
}

.sidebar-scroll-chrome {
  position: sticky;
  top: 0;
  z-index: 18;
  height: 0;
  overflow: visible;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.sidebar-scroll-chrome .scroll-progress-track {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1;
}

.sidebar-scroll-chrome.is-active {
  opacity: 1;
}

