.content-loading-shimmer {
  position: relative;
  overflow: hidden;
  background: rgba(226, 232, 240, 0.88);
}

.content-loading-shimmer::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.55) 45%,
    rgba(255, 255, 255, 0.85) 50%,
    rgba(255, 255, 255, 0.55) 55%,
    transparent 100%
  );
  animation: content-loading-shimmer 1.35s ease-in-out infinite;
}

.content-loading-nav-slot:nth-child(2)::after {
  animation-delay: 0.12s;
}

.content-loading-nav-slot:nth-child(3)::after {
  animation-delay: 0.24s;
}

.content-loading-nav-slot:nth-child(4)::after {
  animation-delay: 0.36s;
}

.content-loading-nav-slot:nth-child(5)::after {
  animation-delay: 0.48s;
}

.content-loading-nav-panel:nth-child(2)::after {
