}

.content-loading-nav-panel:nth-child(3)::after {
  animation-delay: 0.32s;
}

.content-loading-editor-line:nth-child(2)::after {
  animation-delay: 0.08s;
}

.content-loading-editor-line:nth-child(3)::after {
  animation-delay: 0.16s;
