  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 10px 18px;
  background: rgba(248, 250, 252, 0.82);
}

.node-entry-overview-hero-nav {
  border-bottom: 1px solid rgba(148, 163, 184, 0.24);
}

.node-navigation-manifest-nav {
  margin-top: 14px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 10px;
}

.node-navigation-topic-nav-bottom {
  margin-top: 0;
  margin-bottom: 14px;
}

.node-navigation-manifest-nav .node-navigation-manifest-nav-btn:first-child,
.node-entry-overview-hero-nav .node-navigation-manifest-nav-btn:first-child {
  justify-self: start;
  max-width: 100%;
}

.node-navigation-manifest-nav .node-navigation-manifest-nav-btn--up,
.node-entry-overview-hero-nav .node-navigation-manifest-nav-btn--up {
  justify-self: center;
  flex: 0 0 auto;
  max-width: none;
  min-width: max-content;
  overflow: visible;
  white-space: nowrap;
}

.node-navigation-manifest-nav .node-navigation-manifest-nav-btn:last-child,
.node-navigation-manifest-nav .node-navigation-manifest-nav-spacer:last-child,
.node-entry-overview-hero-nav .node-navigation-manifest-nav-btn:last-child,
.node-entry-overview-hero-nav .node-navigation-manifest-nav-spacer:last-child {
  justify-self: end;
  max-width: 100%;
}

.node-navigation-manifest-nav-spacer {
  display: block;
  min-width: 0;
}

.node-navigation-manifest-nav-btn:not(.node-navigation-manifest-nav-btn--up) {
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.node-navigation-manifest-nav-btn:hover:not(:disabled) {
  border-color: #93c5fd;
  background: #eff6ff;
  color: #1d4ed8;
}

.node-navigation-manifest-nav-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.node-navigation-manifest-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 14px;
}

.node-navigation-manifest-actions::before,
.node-navigation-manifest-actions::after {
  content: "";
  flex: 1 1 auto;
  height: 1px;
  background: var(--border);
  min-width: 28px;
}

.node-navigation-manifest-actions .node-navigation-expand-btn {
  flex: 0 0 auto;
  border: 0;
  background: transparent;
  padding: 4px 2px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #dc2626;
}

.node-navigation-manifest-actions .node-navigation-expand-btn:hover {
  background: transparent;
  border-color: transparent;
  color: #b91c1c;
}

.node-navigation-memory-body .file-content-preview p,
.node-navigation-memory-body .file-content-preview ul,
.node-navigation-memory-body .file-content-preview ol,
.node-navigation-memory-body .file-content-preview blockquote,
.node-navigation-memory-body .file-content-preview pre {
  margin: 0 0 0.65em;
}

.node-navigation-memory-body .file-content-preview p:last-child,
.node-navigation-memory-body .file-content-preview ul:last-child,
.node-navigation-memory-body .file-content-preview ol:last-child {
  margin-bottom: 0;
}

.file-content-preview ul.contains-task-list,
.file-content-preview ol.contains-task-list {
  list-style: none;
  padding-left: 0;
}

.file-content-preview li.task-list-item {
  position: relative;
  list-style: none;
  margin: 0 0 0.35em;
  padding-left: 1.65em;
}

.file-content-preview li.task-list-item:last-child {
  margin-bottom: 0;
}

.file-content-preview li.task-list-item .task-list-item-checkbox {
  position: absolute;
  left: 0;
  top: 0.15em;
  width: 1em;
  height: 1em;
  margin: 0;
  accent-color: #2563eb;
  pointer-events: none;
}

.file-content-preview li.task-list-item.checked {
  color: #64748b;
  text-decoration: line-through;
  text-decoration-color: rgba(100, 116, 139, 0.55);
}

.node-navigation-memory-body .tabular-table-wrap {
  margin: 0;
}

.node-navigation-book-toc {
  margin: 0;
}

.nav-book-toc-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-book-toc-folder {
  margin: 0 0 6px;
}

.nav-book-toc-folder-head {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  align-items: center;
  gap: 0;
  margin-left: 0;
}

.nav-book-toc-folder-toggle,
.nav-book-toc-folder-toggle-spacer {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
}

.nav-book-toc-folder-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: #64748b;
  cursor: pointer;
  border-radius: 6px;
}

.nav-book-toc-folder-toggle:hover,
.nav-book-toc-folder-toggle:focus-visible {
  color: var(--accent);
  background: rgba(37, 99, 235, 0.08);
}

.nav-book-toc-folder-toggle:focus-visible {
  outline: 2px solid rgba(37, 99, 235, 0.35);
  outline-offset: 1px;
}

.nav-book-toc-folder-toggle:disabled {
  opacity: 0.45;
  cursor: default;
}

.nav-book-toc-folder-toggle:disabled:hover,
.nav-book-toc-folder-toggle:disabled:focus-visible {
  color: #64748b;
  background: transparent;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-toggle:disabled {
  background: #f8fafc;
  border-color: #e2e8f0;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-toggle:disabled:hover,
.nav-book-toc-tree--guide .nav-book-toc-folder-toggle:disabled:focus-visible {
  border-color: #e2e8f0;
  background: #f8fafc;
  color: #94a3b8;
}

.nav-book-toc-folder-chevron {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(-45deg);
  transition: transform 0.15s ease;
  margin-top: -2px;
}

.nav-book-toc-folder:not(.is-collapsed) > .nav-book-toc-folder-head .nav-book-toc-folder-chevron {
  transform: rotate(45deg);
  margin-top: -4px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-toggle {
  width: 22px;
  height: 22px;
  border: 1px solid #dbe3ee;
  border-radius: 5px;
  background: #f8fafc;
  color: #64748b;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--root .nav-book-toc-folder-toggle {
  width: 24px;
  height: 24px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--nested .nav-book-toc-folder-toggle {
  width: 20px;
  height: 20px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-toggle:hover,
.nav-book-toc-tree--guide .nav-book-toc-folder-toggle:focus-visible {
  border-color: #bfdbfe;
  background: #eff6ff;
  color: var(--accent);
}

.nav-book-toc-tree--guide .nav-book-toc-folder-toggle .nav-book-toc-folder-chevron {
  width: 8px;
  height: 8px;
  border-width: 2px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder.is-collapsed > .nav-book-toc-folder-head .nav-book-toc-folder-chevron {
  transform: rotate(-45deg);
  margin-top: -1px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder:not(.is-collapsed) > .nav-book-toc-folder-head .nav-book-toc-folder-chevron {
  transform: rotate(45deg);
  margin-top: -3px;
}

.nav-book-toc-folder-count {
  flex-shrink: 0;
  min-width: 22px;
  margin-right: 8px;
  padding: 2px 7px;
  border-radius: 999px;
  background: #e2e8f0;
  color: #475569;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.3;
  text-align: center;
}

.nav-book-toc-folder-count.is-expanded-visible {
  background: #f1f5f9;
  color: #64748b;
  font-weight: 600;
}

.nav-book-toc-folder > .nav-book-toc-list {
  margin: 4px 0 0 10px;
  padding: 2px 0 6px 10px;
  border-left: 2px solid #e8edf2;
}

.nav-book-toc-tree--guide {
  --nav-toc-line: #cbd5e1;
  --nav-toc-spine: 14px;
  --nav-toc-branch-pad: 12px;
}

.nav-book-toc-tree--guide .nav-book-toc-list--root {
  margin: 0;
  padding: 0 0 8px var(--nav-toc-spine);
  border-left: 1.5px solid var(--nav-toc-line);
  overflow: visible;
}

.nav-book-toc-tree--guide .nav-book-toc-list--root > .nav-book-toc-folder--root {
  margin-left: calc(-1 * var(--nav-toc-spine));
}

.nav-book-toc-tree--guide .nav-book-toc-folder,
.nav-book-toc-tree--guide .nav-book-toc-list,
.nav-book-toc-tree--guide .nav-book-toc-entry {
  overflow: visible;
}

.nav-book-toc-tree--guide .nav-book-toc-folder {
  margin-bottom: 2px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--root {
  margin-bottom: 8px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--root > .nav-book-toc-folder-head {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: linear-gradient(180deg, #fff 0%, #f8fafc 100%);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
  padding: 5px 8px 5px 6px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--nested > .nav-book-toc-folder-head {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 0;
  background: transparent;
  box-shadow: none;
  min-height: 26px;
  padding-left: 2px;
  position: relative;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-head .nav-book-toc-folder-label {
  /* Shrink-wrap to title; do not stretch across the whole row */
  flex: 0 1 auto;
  min-width: 0;
  width: max-content;
  max-width: 100%;
  overflow: hidden;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-leaders {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  flex-shrink: 0;
  min-width: max-content;
  margin: 0;
  margin-left: auto;
  gap: 4px;
  height: auto;
  background: none;
  overflow: visible;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-leaders::before {
  content: "";
  flex: 1 1 auto;
  min-width: 8px;
  height: 0;
  margin-right: 4px;
  border-bottom: 1px dotted var(--nav-toc-line);
}

.nav-book-toc-tree--guide .nav-book-toc-folder-leaders .nav-book-toc-folder-count {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  margin: 0;
  padding: 0 5px;
  border: 1px solid #cbd5e1;
  border-radius: 999px;
  background: #ffffff;
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  box-sizing: border-box;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-leaders .nav-book-toc-folder-count.is-expanded-visible {
  background: #f1f5f9;
  border-color: #cbd5e1;
  color: #475569;
  font-weight: 700;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-create-btn {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  margin: 0;
  padding: 0;
  border: 1px solid #cbd5e1;
  border-radius: 999px;
  background: #ffffff;
  color: #475569;
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  box-sizing: border-box;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-create-btn:hover,
.nav-book-toc-tree--guide .nav-book-toc-folder-create-btn:focus-visible {
  border-color: #94a3b8;
  background: #eff6ff;
  color: #1d4ed8;
  outline: none;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-head:has(.nav-book-toc-folder-label.is-current) .nav-book-toc-folder-create-btn {
  border-color: rgba(37, 99, 235, 0.35);
  background: rgba(239, 246, 255, 0.95);
  color: #1d4ed8;
}

.nav-book-toc-tree--guide .nav-book-toc-folder-leaders.has-nav-book-toc-folder-create-btn .nav-book-toc-folder-count {
  margin-right: 0;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--root > .nav-book-toc-folder-head {
  overflow: visible;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--nested > .nav-book-toc-folder-head::before {
  content: "";
  position: absolute;
  left: calc(-1 * var(--nav-toc-branch-pad));
  top: 50%;
  width: calc(var(--nav-toc-branch-pad) - 1px);
  border-top: 1.5px solid var(--nav-toc-line);
  pointer-events: none;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--nested .nav-book-toc-folder-toggle-spacer {
  width: 20px;
  height: 20px;
}

.nav-book-toc-tree--guide .nav-book-toc-folder > .nav-book-toc-list {
  margin: 4px 0 2px var(--nav-toc-spine);
  padding: 2px 0 4px var(--nav-toc-branch-pad);
  border-left: 1.5px solid var(--nav-toc-line);
  overflow: visible;
}

.nav-book-toc-tree--guide .nav-book-toc-folder--root > .nav-book-toc-list {
  margin-top: 4px;
}

.nav-book-toc-tree--guide .nav-book-toc-entry {
  position: relative;
}

.nav-book-toc-tree--guide .nav-book-toc-link {
  position: relative;
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  min-width: 0;
  padding: 3px 6px;
  border-radius: 5px;
  box-sizing: border-box;
  overflow: visible;
}

.nav-book-toc-tree--guide .nav-book-toc-link-text {
  flex: 1 1 auto;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  justify-content: flex-start;
}

.nav-book-toc-link-text > .nav-book-toc-title-text {
  flex: 1 1 auto;
  min-width: 0;
}

.nav-book-toc-tree--guide .nav-book-toc-link > .nav-book-toc-link-preview,
.nav-book-toc-tree--guide .nav-book-toc-link > .nav-book-toc-link-icon,
.nav-book-toc-tree--guide .nav-book-toc-link > .nav-book-toc-link-leading,
