  flex-shrink: 0;
  gap: 4px;
  min-width: 0;
  height: auto;
  margin-left: 6px;
  background: none;
}

.nav-book-toc-tree--guide .nav-book-toc-leaders.has-nav-book-toc-attachments-badge::before,
.nav-book-toc-tree--guide .nav-book-toc-leaders.has-nav-book-toc-materials-badge::before,
.nav-book-toc-tree--guide .nav-book-toc-leaders.has-nav-book-toc-unread-badge::before,
.nav-book-toc-tree--guide .nav-book-toc-leaders.has-nav-book-toc-link-indicators::before {
