}

.nav-book-toc-tree--guide .nav-book-toc-folder > .nav-book-toc-list .nav-book-toc-link::before {
  content: "";
  position: absolute;
  left: calc(-1 * var(--nav-toc-branch-pad));
  top: 50%;
  width: calc(var(--nav-toc-branch-pad) - 1px);
  border-top: 1.5px solid var(--nav-toc-line);
