  background: color-mix(in srgb, var(--repo-stat-accent, #6366f1) 22%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--repo-stat-accent, #6366f1) 28%, transparent);
}

.repository-workspace-dashboard.is-light .repository-workspace-stat-icon {
  width: 2rem;
  height: 2rem;
  margin-bottom: 0.55rem;
  border-radius: 10px;
  font-size: 1rem;
  background: color-mix(in srgb, var(--repo-stat-accent, #6366f1) 12%, white);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--repo-stat-accent, #6366f1) 18%, transparent);
}

.repository-workspace-stat-value {
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1.15;
  color: #f8fafc;
}

.repository-workspace-dashboard.is-light .repository-workspace-stat-value {
