  font-size: 0.8125rem;
  font-weight: 600;
  color: rgba(248, 250, 252, 0.9);
}

.repository-workspace-dashboard.is-light .repository-workspace-ext-bars-title {
  margin-bottom: 10px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
