.menu-card--gallery:not(.active):not(:hover):not(:focus-within) .menu-card-cover-icon {
  opacity: 0.72;
  filter: saturate(0.75);
}

.menu-card--gallery:is(:hover, :focus-within, .active) .menu-card-cover-icon {
