/* Вложенные пункты обзора — «веточки» от заголовка секции */
.node-overview-branch-list {
  position: relative;
  margin-left: 8px;
  padding-left: 22px;
}

.node-overview-branch-list::before {
  content: "";
  position: absolute;
  left: 0;
  top: 10px;
  bottom: 10px;
  width: 2px;
  border-radius: 2px;
  background: linear-gradient(180deg, #b8c5d4 0%, #d5dee8 45%, #b8c5d4 100%);
  pointer-events: none;
}

.node-overview-branch-list:has(> :only-child)::before {
  top: 0;
  bottom: 50%;
}

.node-overview-branch-list > * {
  position: relative;
}

.node-overview-branch-list > *::before {
  content: "";
  position: absolute;
  left: -22px;
  top: 50%;
  width: 16px;
  height: 2px;
  background: #b8c5d4;
  transform: translateY(-50%);
  pointer-events: none;
  transition: background-color 0.15s ease;
}

.node-overview-branch-list > *::after {
  content: "";
  position: absolute;
  left: -25px;
  top: 50%;
  width: 7px;
  height: 7px;
  margin-top: -3.5px;
  border-radius: 50%;
  background: #f8fafc;
  border: 2px solid #94a3b8;
  box-sizing: border-box;
  pointer-events: none;
  z-index: 1;
  transition: border-color 0.15s ease, background-color 0.15s ease;
}

.node-overview-branch-list > *:hover::before,
.node-overview-branch-list > *:focus-visible::before {
  background: #7c93a8;
}

.node-overview-branch-list > *:hover::after,
.node-overview-branch-list > *:focus-visible::after {
  border-color: #64748b;
  background: #fff;
}

