  border: 1px solid #c7d2fe;
}

.discuss-aside-tab {
  flex: 1;
  min-width: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #4338ca;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
  padding: 7px 8px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, box-shadow 0.15s;
}

.discuss-aside-tabs:has(.discuss-aside-tab:nth-child(3)) .discuss-aside-tab {
  font-size: 11px;
  padding: 7px 5px;
}

.discuss-aside-tab:hover:not(.is-active) {
  background: rgba(255, 255, 255, 0.65);
}

.discuss-aside-tab.is-active {
  background: #fff;
  color: #312e81;
  box-shadow: 0 1px 3px rgba(99, 102, 241, 0.18);
}

.discuss-aside-tab:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 1px;
}

.discuss-aside-view {
  display: none;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  flex-direction: column;
}

.discuss-aside-view.is-active {
  display: flex;
  flex-direction: column;
}

.discuss-agent-preview-wrap {
  flex-shrink: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  border-bottom: 1px solid var(--border);
  box-sizing: border-box;
  width: 100%;
  overflow: hidden;
  background: #0f172a;
}

.discuss-aside > .discuss-agent-preview-wrap.agent-preview-wrap {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: #0f172a;
}

.discuss-aside > .discuss-agent-preview-wrap.agent-preview-portrait:not(.hidden) {
  animation: none;
}

.discuss-aside > .discuss-agent-preview-wrap .agent-preview-frame {
  border-radius: 0;
  height: auto;
  max-height: none;
}

.discuss-aside > .discuss-agent-preview-wrap .agent-preview-thumb {
  display: block;
  width: 100%;
  height: 120px;
  max-height: none;
  object-fit: cover;
  object-position: center 28%;
}

.discuss-agent-preview-wrap.agent-preview-openable {
  cursor: pointer;
}

.discuss-agent-preview-wrap.agent-preview-openable:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
}

.discuss-aside-shell-view {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  background: #0f1020;
  position: relative;
}

.discuss-voice-chat-dropzone {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 16px;
  border: 2px dashed transparent;
  background: rgba(15, 16, 32, 0.72);
  color: #e0e7ff;
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  pointer-events: none;
}

body.is-voice-chat-drop-active .discuss-voice-chat-dropzone {
  display: flex;
  pointer-events: auto;
}

body.is-voice-chat-drop-active .discuss-voice-chat-dropzone.is-active,
.discuss-aside.is-voice-chat-drop-target .discuss-voice-chat-dropzone.is-active {
  border-color: #818cf8;
  background: rgba(49, 46, 129, 0.82);
  box-shadow: inset 0 0 0 1px rgba(129, 140, 248, 0.35);
}

.is-dragging-voice-chat-context,
.is-dragging-menu-link {
  opacity: 0.72;
}

#app-footer-ideas-btn[draggable="true"],
#agent-todo-preview-toggle[draggable="true"] {
  cursor: grab;
}

#app-footer-ideas-btn.is-dragging-voice-chat-context,
#agent-todo-preview-toggle.is-dragging-voice-chat-context {
  cursor: grabbing;
}

.discuss-aside.is-voice-chat-drop-target {
  box-shadow: inset 0 0 0 2px #6366f1;
}

body.is-cms-page-picker-active {
  cursor: crosshair;
}

body.is-cms-page-picker-active #discuss-aside,
body.is-cms-page-picker-active #discuss-aside * {
  cursor: default;
}

.cms-page-picker-root {
  position: fixed;
  inset: 0;
  z-index: 12000;
  pointer-events: none;
  display: none;
}

.cms-page-picker-root.is-active {
  display: block;
}

.cms-page-picker-hint {
  position: fixed;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 12002;
  max-width: min(92vw, 520px);
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.92);
  color: #e2e8f0;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  box-shadow: 0 8px 28px rgba(15, 23, 42, 0.28);
  pointer-events: none;
}

.cms-page-picker-highlight {
  position: fixed;
  z-index: 12001;
  display: none;
  border: 2px solid #6366f1;
  border-radius: 6px;
  background: rgba(99, 102, 241, 0.12);
  box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.35), inset 0 0 0 1px rgba(255, 255, 255, 0.35);
  pointer-events: none;
  transition: top 0.05s ease, left 0.05s ease, width 0.05s ease, height 0.05s ease;
}

.cms-page-picker-highlight-tag {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 1;
  max-width: calc(100% - 8px);
  padding: 2px 7px;
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.92);
  color: #c7d2fe;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.02em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.24);
  pointer-events: none;
}

.cms-page-picker-highlight-tag[hidden] {
  display: none;
}

.discuss-shell-iframe {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: #0f1020;
}

.discuss-aside-title {
  margin: 0;
  font-size: 14px;
  font-weight: 700;
  color: var(--text);
}

.discuss-aside-sub {
  margin: 2px 0 0;
  font-size: 11px;
  color: var(--muted);
  line-height: 1.35;
}

.discuss-aside-close-btn {
  border: 0;
  background: transparent;
  color: var(--muted);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  padding: 0 4px;
}

.discuss-aside-close-btn:hover {
  color: var(--text);
}

.discuss-context-section {
  flex-shrink: 0;
  padding: 10px 12px 8px 14px;
  border-bottom: 1px solid var(--border);
}

.discuss-context-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.discuss-context-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.discuss-context-add-btn {
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
  font-size: 11px;
  padding: 3px 8px;
  cursor: pointer;
}

.discuss-context-add-btn:hover:not(:disabled) {
  border-color: #93c5fd;
  color: #1d4ed8;
}

.discuss-context-add-btn:disabled {
  opacity: 0.45;
  cursor: default;
}

.discuss-context-dropzone {
  min-height: 56px;
  border: 1px dashed #c7d2fe;
  border-radius: 10px;
  background: #fff;
  padding: 8px;
  transition: border-color 0.15s, background 0.15s;
}

.discuss-context-dropzone.is-drop-target {
  border-color: #6366f1;
  background: #eef2ff;
}

.discuss-context-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.discuss-context-chip {
  display: flex;
  align-items: stretch;
  gap: 4px;
}

.discuss-context-chip-main {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: #f8fafc;
  padding: 6px 8px;
  text-align: left;
  cursor: pointer;
  font-size: 12px;
  color: var(--text);
}

.discuss-context-chip-main:hover {
  border-color: #93c5fd;
  background: #eff6ff;
}

.discuss-context-chip-icon {
  flex-shrink: 0;
}

.discuss-context-chip-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.discuss-context-chip-remove {
  flex-shrink: 0;
  width: 28px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: #fff;
  color: var(--muted);
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
}

.discuss-context-chip-remove:hover {
  color: #b91c1c;
  border-color: #fecaca;
  background: #fef2f2;
}

.discuss-context-hint {
  margin: 0;
  font-size: 11px;
  color: var(--muted);
  line-height: 1.4;
}

.discuss-messages-panel {
  position: relative;
  flex: 1 1 auto;
  min-height: 96px;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.discuss-messages-scroll-host {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.discuss-messages-scroll-host > .discuss-messages-wrap {
  flex: 1 1 auto;
  min-height: 0;
}

.discuss-messages-wrap {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 10px 12px 14px 14px;
}

.discuss-messages-scroll-chrome {
  position: sticky;
  top: -10px;
  z-index: 3;
  margin: -10px -12px 8px -14px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.discuss-messages-scroll-chrome .scroll-depth-indicator {
  top: 10px;
  right: 12px;
}

.discuss-messages-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.discuss-messages-empty {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

.discuss-message {
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: #fff;
  padding: 8px 10px;
}

.discuss-message--assistant {
  border-color: #ddd6fe;
  background: #f5f3ff;
}

.discuss-message--system {
  border-color: #fde68a;
  background: #fffbeb;
}

.discuss-message-head {
  font-size: 10px;
  font-weight: 700;
  color: var(--muted);
  margin-bottom: 4px;
}

.discuss-message-body {
  font-size: 12px;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
}

.discuss-composer {
  flex: 0 0 auto;
  margin-top: auto;
  border-top: 1px solid var(--border);
  padding: 10px 12px 12px 14px;
  background: #fff;
  box-shadow: 0 -10px 24px rgba(15, 23, 42, 0.06);
  z-index: 1;
}

.discuss-composer-input {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 10px;
  font: inherit;
  font-size: 12px;
  line-height: 1.45;
  resize: vertical;
  min-height: 72px;
}

.discuss-composer-input:focus {
  outline: none;
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}

.discuss-composer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.discuss-composer-btn {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  font-size: 12px;
  padding: 6px 10px;
  cursor: pointer;
}

.discuss-composer-btn:hover {
  border-color: #93c5fd;
  background: #f8fafc;
}

.discuss-composer-btn--primary {
  background: #4f46e5;
  border-color: #4f46e5;
  color: #fff;
}

.discuss-composer-btn--primary:hover {
  background: #4338ca;
  border-color: #4338ca;
}

.discuss-composer-btn--ghost {
  color: var(--muted);
}

.discuss-panel-toggle-btn.is-active {
  border-color: #6366f1;
  background: #eef2ff;
  color: #4338ca;
}

.header-tool-btn.discuss-panel-toggle-btn {
  position: relative;
}

.discuss-panel-context-badge {
  position: absolute;
  top: 2px;
  right: 2px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 14px;
  height: 14px;
  padding: 0 3px;
  border-radius: 999px;
  background: #6366f1;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  line-height: 1;
}

@media (max-width: 960px) {
  .app.app-landing-view.app-landing-discuss-open {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr) auto;
  }

  .app.app-landing-view.app-landing-discuss-open .app-landing-pane:not(.hidden) {
    grid-column: 1;
    grid-row: 2 / 3;
  }

  .app.app-landing-view.app-landing-discuss-open .workspace-pane,
  .app.home-view.app-home-discuss-open .workspace-pane {
    grid-column: 1;
    grid-row: 2 / 3;
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 40;
    max-height: 42vh;
    border-top: 3px solid #6366f1;
    background: #fafbff;
    box-shadow: 0 -8px 32px rgba(15, 23, 42, 0.18);
  }

  .app.home-view.app-home-discuss-open {
    grid-template-columns: var(--sidebar-width) var(--sidebar-resize-bar-width) minmax(0, 1fr);
  }

  .app.home-view.app-home-discuss-open .agent-canvas-pane:not(.hidden) {
    grid-column: 3;
    grid-row: 2 / 3;
  }

  .workspace-body {
    flex-direction: column;
  }

  .discuss-aside {
    flex: 0 0 auto;
    width: 100%;
    max-width: none;
    min-width: 0;
    border-left: 0;
    border-top: 3px solid #6366f1;
    max-height: 38vh;
  }

  .discuss-aside-resizer {
    display: none;
  }
}

/* ── Node overview: type-specific custom fields form ─────────────────────── */

.node-type-fields-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 2px 0 4px;
}

.node-type-field-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.node-type-field-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted, #64748b);
  letter-spacing: 0.01em;
  cursor: default;
}

.node-type-field-required {
  color: #ef4444;
  font-weight: 700;
}

.type-field-ctrl {
  width: 100%;
  padding: 7px 10px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text, #1e293b);
  background: var(--surface, #fff);
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 7px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
  box-sizing: border-box;
}

.type-field-ctrl:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.12);
}

.type-field-ctrl--textarea {
  resize: vertical;
  min-height: 70px;
  font-family: inherit;
}

.type-field-ctrl--select {
  cursor: pointer;
}

.type-field-ctrl--color {
  padding: 2px 6px;
  height: 34px;
  cursor: pointer;
}

.type-field-ctrl--boolean {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text, #1e293b);
  cursor: pointer;
  user-select: none;
}

.type-field-ctrl--boolean input[type="checkbox"] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: #6366f1;
}

.node-type-fields-footer {
  display: flex;
  justify-content: flex-end;
  padding-top: 4px;
  border-top: 1px solid var(--border, #e2e8f0);
  margin-top: 4px;
}

.node-type-fields-save-btn {
  padding: 7px 20px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  background: #6366f1;
  border: none;
  border-radius: 7px;
  cursor: pointer;
  transition: background 0.15s, opacity 0.15s;
}

.node-type-fields-save-btn:hover {
  background: #4f46e5;
}

.node-type-fields-save-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

