/* ── Status pages: maintenance (503) + shared with 404 layout ── */
.status-standalone {
  margin: 0;
  min-height: 100vh;
  background: #fffbeb;
}

.status-standalone--maintenance {
  background: #fffbeb;
}

.status-page,
.maintenance-pane {
  position: relative;
  min-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px 20px 48px;
  box-sizing: border-box;
  overflow: hidden;
}

.status-standalone .status-page {
  min-height: 100vh;
}

.maintenance-pane {
  align-items: center;
  justify-content: center;
  padding: 0;
}

.status-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 70% 55% at 12% 8%, rgba(245, 158, 11, 0.22), transparent 60%),
    radial-gradient(ellipse 65% 50% at 88% 18%, rgba(251, 191, 36, 0.18), transparent 55%),
    radial-gradient(ellipse 55% 45% at 72% 88%, rgba(249, 115, 22, 0.14), transparent 50%),
    radial-gradient(ellipse 40% 35% at 28% 72%, rgba(234, 179, 8, 0.1), transparent 45%),
    linear-gradient(160deg, #fff7ed 0%, #fffbeb 42%, #fefce8 100%);
}

.status-bg::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.45;
  background-image:
    linear-gradient(rgba(217, 119, 6, 0.1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(217, 119, 6, 0.1) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: radial-gradient(ellipse 85% 75% at 50% 45%, #000 20%, transparent 100%);
}

.status-orbit {
  position: absolute;
  border-radius: 999px;
  border: 1px dashed rgba(245, 158, 11, 0.22);
  pointer-events: none;
  animation: not-found-orbit-spin 28s linear infinite;
}

.status-orbit--one {
  width: min(520px, 90vw);
  height: min(520px, 90vw);
  top: 8%;
  right: -8%;
}

.status-orbit--two {
  width: min(360px, 70vw);
  height: min(360px, 70vw);
  bottom: 4%;
  left: -6%;
  animation-direction: reverse;
  animation-duration: 36s;
}

.status-inner {
  position: relative;
  z-index: 1;
  width: min(640px, 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 14px;
}

.status-visual {
  position: relative;
  width: min(280px, 72vw);
  height: 120px;
  margin-bottom: 4px;
}

.status-code {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: clamp(4.5rem, 16vw, 7rem);
  font-weight: 900;
  letter-spacing: -0.06em;
  line-height: 1;
  background: linear-gradient(135deg, rgba(180, 83, 9, 0.16) 0%, rgba(217, 119, 6, 0.12) 45%, rgba(234, 179, 8, 0.1) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  user-select: none;
}

.status-mascot {
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: 56px;
  height: 56px;
  animation: not-found-mascot-float 4s ease-in-out infinite;
}

.status-mascot--service .status-mascot-face {
  width: 56px;
  height: 56px;
  border-radius: 18px;
  background: linear-gradient(180deg, #fde68a 0%, #f59e0b 100%);
  border: 2px solid rgba(180, 83, 9, 0.28);
  box-shadow: 0 10px 24px rgba(180, 83, 9, 0.18);
  position: relative;
}

.status-mascot-antenna {
  position: absolute;
  top: -14px;
  left: 50%;
  width: 2px;
  height: 12px;
  margin-left: -1px;
  background: #b45309;
  border-radius: 999px;
}

.status-mascot-antenna::after {
  content: "";
  position: absolute;
  top: -5px;
  left: 50%;
  width: 8px;
  height: 8px;
  margin-left: -4px;
  border-radius: 999px;
  background: #fbbf24;
  box-shadow: 0 0 10px rgba(251, 191, 36, 0.8);
  animation: not-found-antenna-blink 2.4s ease-in-out infinite;
}

.status-mascot-eye {
  position: absolute;
  top: 18px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #78350f;
}

.status-mascot-eye:first-of-type {
  left: 14px;
}

.status-mascot-eye:last-of-type {
  right: 14px;
}

.status-mascot-mouth {
  position: absolute;
  left: 50%;
  bottom: 12px;
  width: 16px;
  height: 4px;
  margin-left: -8px;
  border-radius: 999px;
  background: rgba(120, 53, 15, 0.55);
}

.status-mascot-badge {
  position: absolute;
  right: -8px;
  bottom: -4px;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: #fff7ed;
  border: 1px solid rgba(217, 119, 6, 0.35);
  font-size: 12px;
  box-shadow: 0 6px 14px rgba(180, 83, 9, 0.16);
}

.status-eyebrow {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #b45309;
}

.status-title {
  margin: 0;
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  line-height: 1.15;
  color: #7c2d12;
}

.status-lead {
  margin: 0;
  max-width: 52ch;
  font-size: 15px;
  line-height: 1.6;
  color: #92400e;
}

.status-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  margin-top: 6px;
}

.status-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid rgba(217, 119, 6, 0.28);
  background: rgba(255, 255, 255, 0.92);
  color: #9a3412;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}

.status-btn:hover {
  transform: translateY(-1px);
  border-color: rgba(217, 119, 6, 0.45);
  box-shadow: 0 10px 24px rgba(180, 83, 9, 0.12);
}

.status-btn--primary {
  border-color: transparent;
  background: linear-gradient(135deg, #f59e0b 0%, #ea580c 100%);
  color: #fff7ed;
  box-shadow: 0 12px 28px rgba(234, 88, 12, 0.28);
}

.status-btn--primary:hover {
  border-color: transparent;
  box-shadow: 0 14px 28px rgba(234, 88, 12, 0.34);
}

.status-footnote {
  margin: 10px 0 0;
  font-size: 13px;
  font-style: italic;
  color: #d97706;
}

.app.maintenance-view {
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
  overflow: hidden;
}

.app.maintenance-view .app-header,
.app.maintenance-view .app-footer,
.app.maintenance-view #app-footer,
.app.maintenance-view .content-search-wrap,
.app.maintenance-view .sidebar-shell,
.app.maintenance-view .sidebar,
.app.maintenance-view .sidebar-resize-bar,
.app.maintenance-view .workspace-pane {
  display: none !important;
}

.app.maintenance-view .agent-canvas-pane:not(#maintenance-pane) {
  display: none !important;
}

.app.maintenance-view #maintenance-pane.agent-canvas-pane:not(.hidden) {
  display: flex;
  grid-row: 1 / -1;
  grid-column: 1 / -1;
  min-height: 100%;
}

@media (max-width: 640px) {
  .status-actions {
    width: 100%;
    flex-direction: column;
  }

  .status-btn {
    width: 100%;
  }
}

/* ── Mobile viewport blocker (≤900px) ── */
.app-mobile-blocker {
  display: none;
}

@media (max-width: 900px) {
  .app-mobile-blocker {
    position: fixed;
    inset: 0;
    z-index: 10150;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 28px 18px 40px;
    box-sizing: border-box;
    overflow: hidden;
    touch-action: none;
  }

  html:has(#app-mobile-blocker),
  body:has(#app-mobile-blocker) {
    overflow: hidden !important;
  }

  .app-mobile-blocker-bg {
    background:
      radial-gradient(ellipse 70% 55% at 10% 12%, rgba(236, 72, 153, 0.2), transparent 58%),
      radial-gradient(ellipse 65% 50% at 90% 16%, rgba(59, 130, 246, 0.18), transparent 55%),
      radial-gradient(ellipse 55% 45% at 70% 88%, rgba(167, 139, 250, 0.16), transparent 50%),
      linear-gradient(160deg, #fdf2f8 0%, #f8fafc 42%, #eff6ff 100%);
  }

  .app-mobile-blocker-code {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: clamp(4rem, 18vw, 6.5rem);
    line-height: 1;
    filter: grayscale(0.15) saturate(1.1);
    opacity: 0.92;
    user-select: none;
    animation: app-mobile-blocker-phone-wobble 3.2s ease-in-out infinite;
  }

  .app-mobile-blocker-mascot {
    z-index: 1;
  }

  .app-mobile-blocker-mascot-badge {
    position: absolute;
    right: -10px;
    bottom: -4px;
    font-size: 22px;
    line-height: 1;
    transform: rotate(12deg);
    filter: drop-shadow(0 4px 8px rgba(15, 23, 42, 0.12));
    animation: app-mobile-blocker-badge-pop 2.8s ease-in-out infinite;
  }

  .app-mobile-blocker-eyebrow {
    color: #db2777;
  }

  .app-mobile-blocker-emoji {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 10px 14px;
    margin-top: 4px;
    font-size: clamp(1.35rem, 5vw, 1.75rem);
    line-height: 1;
  }

  .app-mobile-blocker-emoji span {
    display: inline-block;
    animation: app-mobile-blocker-emoji-bounce 2.4s ease-in-out infinite;
  }

  .app-mobile-blocker-emoji span:nth-child(2) {
    animation-delay: 0.12s;
  }

  .app-mobile-blocker-emoji span:nth-child(3) {
    animation-delay: 0.24s;
  }

  .app-mobile-blocker-emoji span:nth-child(4) {
    animation-delay: 0.36s;
  }

  .app-mobile-blocker-emoji span:nth-child(5) {
    animation-delay: 0.48s;
  }

  .app-mobile-blocker-emoji span:nth-child(6) {
    animation-delay: 0.6s;
  }

  .app-mobile-blocker-tip {
    margin: 2px 0 0;
    max-width: 420px;
    font-size: 14px;
    line-height: 1.5;
    color: #64748b;
  }

  .app-mobile-blocker-footnote {
    color: #be185d;
  }
}

@keyframes app-mobile-blocker-phone-wobble {
  0%,
  100% {
    transform: rotate(-6deg) scale(1);
  }
  50% {
    transform: rotate(6deg) scale(1.04);
  }
}

@keyframes app-mobile-blocker-badge-pop {
  0%,
  100% {
    transform: rotate(12deg) scale(1);
  }
  50% {
    transform: rotate(-8deg) scale(1.12);
  }
}

@keyframes app-mobile-blocker-emoji-bounce {
  0%,
  100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-7px);
  }
}

@media (max-width: 900px) and (prefers-reduced-motion: reduce) {
  .app-mobile-blocker-code,
  .app-mobile-blocker-mascot-badge,
  .app-mobile-blocker-emoji span,
  .app-mobile-blocker .not-found-mascot {
    animation: none !important;
  }
}

@media print {
  .app-mobile-blocker {
    display: none !important;
  }
}

/* ── Classic Windows TreeView sidebar ─────────────────────────────────────── */

.sidebar-slab-menu {
  --menu-win-text: #000000;
  --menu-win-muted: #606060;
  --menu-win-line: #808080;
  --menu-win-hover: #e5f3ff;
  --menu-win-active-bg: #316ac5;
  --menu-win-active-text: #ffffff;
  --menu-win-row-h: 24px;
  --menu-win-font: 12px;
  --menu-win-indent: 16px;
  --menu-win-toggle-w: 12px;
  --menu-win-toggle-gap: 4px;
  --menu-win-toggle-slot: calc(var(--menu-win-toggle-w) + var(--menu-win-toggle-gap));
  --menu-win-sort-w: 18px;
  --menu-win-branch-x: calc(var(--menu-win-toggle-w) / 2);
  --menu-win-branch-x-sort: calc(var(--menu-win-sort-w) + var(--menu-win-branch-x));
  --menu-win-branch-w: calc(var(--menu-win-toggle-slot) - var(--menu-win-branch-x));
  --menu-win-label-pad-left: 4px;
  --menu-sidebar-pad-x: 12px;
  --menu-system-file-dot-left: 8px;
  --menu-system-file-dot-size: 8px;
  --menu-system-file-dot-gap: 6px;
}

.sidebar-slab-menu .sidebar-menu-before-tree,
.sidebar-tree-band-panel .sidebar-menu-before-tree {
  padding-left: 0;
  padding-right: 0;
}

.sidebar-slab-menu .menu {
  padding: 0 var(--menu-sidebar-pad-x) 8px;
  background: #ffffff;
  font-family: Tahoma, "Segoe UI", "MS Sans Serif", sans-serif;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) {
  font-size: var(--menu-win-font);
}

/* Rows */
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-folder,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-section-row .menu-section-title {
  font-size: var(--menu-win-font);
  line-height: 1.25;
  color: var(--menu-win-text);
  border: none;
  border-radius: 0;
  margin-bottom: 0;
  min-height: var(--menu-win-row-h);
  background: transparent;
  padding: 1px 4px 1px var(--menu-win-label-pad-left);
  display: flex;
  align-items: center;
  box-sizing: border-box;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-folder::before,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item:not(.system-file-item)::before {
  content: none;
  display: none;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-folder.has-menu-tree-status,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item.has-menu-tree-status {
  padding-left: var(--menu-win-label-pad-left);
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-section-row--empty .menu-section-title,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-section-title--empty {
  color: var(--menu-win-muted);
  padding-left: var(--menu-win-label-pad-left);
}

.sidebar-slab-menu
  .menu-agent-pane:not(.is-menu-view-flat)
  .menu-section-row--empty
  .menu-section-title::before {
  content: none;
  display: none;
}

/* Top-level categories — bold like Windows tree roots */
.sidebar-slab-menu
  .menu-agent-pane:not(.is-menu-view-flat)
  .tree-children[data-sort-folder="."]
  > .menu-section
  > .menu-folder-row
  .menu-folder-name,
.sidebar-slab-menu
  .menu-agent-pane:not(.is-menu-view-flat)
  .tree-children[data-sort-folder="."]
  > .menu-section
  > .menu-section-row
  .menu-section-name,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-workspace-head .menu-folder-name,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-service-title,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-shared-title,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-agent-system-title {
  font-weight: 700;
}

/* Nested indent — ровно один шаг на уровень */
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children {
  margin-left: 0;
  margin-top: 0;
  padding-left: var(--menu-win-indent);
  border-left: none;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children .tree-children {
  padding-left: var(--menu-win-indent);
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children.menu-container-body,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-container-section > .tree-children {
  margin-left: 0;
  padding-left: 0;
  border-left: none;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children.menu-workspace-body,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-workspace-root-section > .tree-children {
  margin-left: 0;
  padding-left: 0;
  border-left: none;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children.menu-nested-container-body,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children.menu-service-body,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children.menu-shared-body,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-git-repo-body,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children.menu-agent-system-body,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .tree-children.menu-agent-system-domain-body {
  margin-left: 0;
  padding-left: 0;
  border-left: none;
}

/* Dotted branch lines (веточки) */
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-toggle-spacer {
  box-sizing: border-box;
  width: var(--menu-win-toggle-slot);
  height: var(--menu-win-toggle-w);
  flex: 0 0 var(--menu-win-toggle-slot);
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item-row,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .system-file-row {
  gap: 1px;
  margin-bottom: 0;
  display: flex;
  align-items: center;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch > .menu-folder-row,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch > .menu-section-row,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item-row.menu-tree-branch,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .system-file-row.menu-tree-branch {
  position: relative;
  z-index: 1;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch > .menu-folder-row::before,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch > .menu-section-row::before,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item-row.menu-tree-branch::before,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .system-file-row.menu-tree-branch::before {
  content: "";
  position: absolute;
  left: var(--menu-win-branch-x);
  top: 0;
  bottom: 0;
  border-left: 1px dotted var(--menu-win-line);
  pointer-events: none;
  z-index: 0;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch-last > .menu-folder-row::before,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch-last > .menu-section-row::before,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item-row.menu-tree-branch-last::before,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .system-file-row.menu-tree-branch-last::before {
  bottom: 50%;
}

.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch > .menu-folder-row::after,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-tree-branch > .menu-section-row::after,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .menu-item-row.menu-tree-branch::after,
.sidebar-slab-menu .menu-agent-pane:not(.is-menu-view-flat) .system-file-row.menu-tree-branch::after {
  content: "";
  position: absolute;
  left: var(--menu-win-branch-x);
  top: 50%;
  width: var(--menu-win-branch-w);
  border-top: 1px dotted var(--menu-win-line);
  pointer-events: none;
  z-index: 0;
}

/* Веточки с учётом ⠿-ручки сортировки слева от toggle */
.sidebar-slab-menu
  .menu-agent-pane:not(.is-menu-view-flat)
  .menu-tree-branch
  > .menu-folder-row.menu-sort-row::before,
.sidebar-slab-menu
