.awn-dashboard-shell {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.awn-dashboard-page-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #fff;
}

.awn-dashboard-eyebrow {
  margin: 0 0 4px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #6366f1;
}

.awn-dashboard-title {
  margin: 0 0 6px;
  font-size: 22px;
  font-weight: 800;
  color: #1e3a8a;
}

.awn-dashboard-lead {
  margin: 0;
  font-size: 13px;
  color: #64748b;
}

.awn-dashboard-open-folder-btn {
  flex: 0 0 auto;
  padding: 8px 12px;
  border: 1px solid #dbeafe;
  border-radius: 10px;
  background: #eff6ff;
  color: #1d4ed8;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.awn-dashboard-todo-plaque {
  padding: 16px 18px;
  border: 1px dashed rgba(99, 102, 241, 0.35);
  border-radius: 16px;
  background: rgba(238, 242, 255, 0.55);
}

.awn-dashboard-todo-plaque-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.awn-dashboard-todo-plaque-title {
  margin: 0 0 6px;
  font-size: 18px;
  font-weight: 800;
  color: #1e3a8a;
}

.awn-dashboard-todo-plaque-badge {
  flex: 0 0 auto;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px dashed rgba(99, 102, 241, 0.35);
  background: rgba(255, 255, 255, 0.72);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #4338ca;
}

.awn-dashboard-todo-plaque-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.awn-dashboard-todo-plaque-block {
  padding: 12px 14px;
  border: 1px solid rgba(255, 255, 255, 0.85);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.78);
}

.awn-dashboard-todo-plaque-block h4 {
  margin: 0 0 8px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #4338ca;
}

.awn-dashboard-todo-plaque-block ul {
  margin: 0;
  padding-left: 18px;
  font-size: 12px;
  line-height: 1.55;
  color: #475569;
}

.awn-dashboard-todo-plaque-block li + li {
  margin-top: 6px;
}

.awn-dashboard-todo-plaque-block code {
  font-size: 11px;
}

.awn-dashboard-todo-plaque-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(99, 102, 241, 0.15);
  font-size: 12px;
  color: #64748b;
}

.awn-dashboard-todo-plaque-chat-label {
  font-weight: 700;
  color: #4338ca;
}

.awn-dashboard-todo-plaque-chat-link {
  color: #1d4ed8;
  font-weight: 700;
  text-decoration: none;
}

.awn-dashboard-todo-plaque-chat-link:hover {
  text-decoration: underline;
}

.awn-dashboard-todo-plaque-chat-id {
  padding: 2px 6px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.85);
  font-size: 11px;
  color: #334155;
}

.awn-dashboard-todo-plaque-copy-btn {
  margin-left: auto;
  padding: 6px 10px;
  border: 1px solid #dbeafe;
  border-radius: 8px;
  background: #eff6ff;
  color: #1d4ed8;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

@media (max-width: 760px) {
  .awn-dashboard-todo-plaque-grid {
    grid-template-columns: 1fr;
  }

  .awn-dashboard-todo-plaque-copy-btn {
    margin-left: 0;
  }
}

.awn-dashboard-grid {
  display: grid;
  grid-template-columns: repeat(var(--awn-dashboard-cols, 12), minmax(0, 1fr));
  gap: 14px;
  grid-auto-rows: minmax(96px, auto);
}

.awn-dashboard-widget {
  display: flex;
  flex-direction: column;
  min-height: 96px;
  padding: 14px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.75);
  background: rgba(255, 255, 255, 0.82);
  backdrop-filter: blur(10px);
  box-shadow: 0 12px 32px rgba(59, 130, 246, 0.06);
}

.awn-dashboard-widget-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}

.awn-dashboard-widget-title {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: #1e293b;
}

.awn-dashboard-widget-badge {
  flex: 0 0 auto;
  padding: 2px 7px;
  border-radius: 999px;
  background: #f1f5f9;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  color: #64748b;
}

.awn-dashboard-widget-body {
  flex: 1;
  min-height: 0;
}

.awn-dashboard-widget-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid #e2e8f0;
}

.awn-dashboard-widget-source {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #94a3b8;
}

.awn-dashboard-widget-link {
  border: 0;
  background: transparent;
  padding: 0;
  font-size: 11px;
  font-weight: 700;
  color: #2563eb;
  cursor: pointer;
}

.awn-dashboard-stat-value {
  font-size: 24px;
  font-weight: 800;
  color: #1e3a8a;
  font-variant-numeric: tabular-nums;
}

.awn-dashboard-stat-value.is-error {
  color: #b91c1c;
  font-size: 14px;
}

.awn-dashboard-stat-sub {
  margin-top: 4px;
  font-size: 12px;
  color: #64748b;
}

.awn-dashboard-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.awn-dashboard-list-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  font-size: 13px;
  line-height: 1.4;
  color: #334155;
}

.awn-dashboard-check {
  width: 14px;
  height: 14px;
  margin-top: 2px;
  border-radius: 4px;
  border: 1.5px solid #cbd5e1;
}

.awn-dashboard-list-empty {
  margin: 0;
  font-size: 13px;
  color: #64748b;
}

.awn-dashboard-list-empty.is-error {
  color: #b91c1c;
}

.awn-dashboard-calendar-caption {
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 700;
  color: #1e3a8a;
  text-transform: capitalize;
}

.awn-dashboard-calendar-weekdays,
.awn-dashboard-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
}

.awn-dashboard-calendar-weekdays {
  margin-bottom: 4px;
  font-size: 10px;
  font-weight: 700;
  color: #94a3b8;
  text-align: center;
}

.awn-dashboard-calendar-day {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  border-radius: 6px;
  font-size: 11px;
  color: #334155;
}

.awn-dashboard-calendar-day.is-today {
  background: #2563eb;
  color: #fff;
  font-weight: 700;
}

.awn-dashboard-calendar-day.is-empty {
  visibility: hidden;
}

.awn-dashboard-markdown {
  font-size: 13px;
  line-height: 1.5;
  color: #475569;
  white-space: pre-wrap;
}

.awn-dashboard-stub {
  font-size: 12px;
  line-height: 1.45;
  color: #64748b;
}

.awn-dashboard-stub strong {
  display: block;
  margin-bottom: 4px;
  color: #1e3a8a;
}

.awn-dashboard-stub code,
.awn-dashboard-stub-hint code {
  font-size: 11px;
  background: #f1f5f9;
  padding: 1px 4px;
  border-radius: 4px;
}

.awn-dashboard-stub-hint {
  margin-top: 6px;
  font-size: 11px;
}

.awn-dashboard-activity-item {
  grid-template-columns: auto minmax(0, 1fr);
}

.awn-dashboard-activity-dot {
  width: 8px;
  height: 8px;
  margin-top: 6px;
  border-radius: 50%;
  background: linear-gradient(135deg, #3b82f6, #8b5cf6);
}

.awn-dashboard-activity-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.awn-dashboard-activity-title {
  font-size: 13px;
  font-weight: 600;
  color: #1e293b;
}

.awn-dashboard-activity-meta {
  font-size: 11px;
  color: #94a3b8;
}

.awn-dashboard-bars {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.awn-dashboard-bar-row {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}

.awn-dashboard-bar-label {
  font-size: 11px;
  font-weight: 700;
  color: #64748b;
}

.awn-dashboard-bar-track {
  height: 8px;
  border-radius: 999px;
  background: #e2e8f0;
  overflow: hidden;
}

.awn-dashboard-bar-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2563eb, #60a5fa);
}

.awn-dashboard-bar-value {
  font-size: 11px;
  font-weight: 700;
  color: #1e3a8a;
  font-variant-numeric: tabular-nums;
}

.awn-dashboard-bar-note {
  margin: 10px 0 0;
  font-size: 11px;
  color: #94a3b8;
}

.awn-dashboard-chart {
  min-height: 120px;
}

.awn-dashboard-chart-bars {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(28px, 1fr));
  gap: 8px;
  align-items: end;
  height: 120px;
}

.awn-dashboard-chart-bar-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  height: 100%;
}

.awn-dashboard-chart-bar-fill {
  display: block;
  width: 100%;
  max-width: 36px;
  min-height: 8px;
  border-radius: 6px 6px 2px 2px;
  background: linear-gradient(180deg, #60a5fa, #2563eb);
}

.awn-dashboard-chart-bar-label {
  font-size: 10px;
  font-weight: 700;
  color: #64748b;
}

.awn-dashboard-chart-svg {
  display: block;
  width: 100%;
  height: auto;
}

.awn-dashboard-chart-line {
  fill: none;
  stroke: #2563eb;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.awn-dashboard-chart-dot {
  fill: #fff;
  stroke: #2563eb;
  stroke-width: 2;
}

.awn-dashboard-chart-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  margin-top: 8px;
  font-size: 10px;
  color: #64748b;
}

.awn-dashboard-chart-legend strong {
  color: #1e3a8a;
}

.awn-dashboard-loading,
.awn-dashboard-empty {
  padding: 20px;
  border-radius: 14px;
  border: 1px dashed #cbd5e1;
  background: #f8fafc;
  color: #64748b;
  font-size: 14px;
}

.awn-dashboard-empty-hint {
  margin: 8px 0 0;
  font-size: 12px;
}

.menu-awn-temp-stats {
  margin: 0 0 0.5rem;
  font-size: 0.8125rem;
  line-height: 1.35;
  color: #374151;
}

.menu-awn-temp-stats.is-empty {
  color: #6b7280;
}

.menu-awn-temp-stats.is-error {
  color: #b91c1c;
}

.node-journal {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  padding: 0;
  display: flex;
  flex-direction: column;
}

.node-journal-content,
.workspace-journal-host {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: none;
  margin: 0;
}

.node-journal .workspace-journal-host,
.node-journal .workspace-journal-panel {
  flex: 1 1 auto;
  min-height: 0;
  max-height: none;
}

.node-journal .workspace-journal-list {
  min-height: 0;
  padding: 14px 18px 24px;
  gap: 12px;
}

.node-journal .workspace-journal-item {
  padding: 14px 16px;
}

.node-journal .workspace-journal-item-path-row {
  margin-top: 10px;
  padding-left: 1px;
}

.workspace-journal-panel {
  flex: 1 1 auto;
  min-height: 320px;
  display: flex;
  flex-direction: column;
  gap: 0;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 14px;
  overflow: clip;
  background: linear-gradient(165deg, #ffffff 0%, #f8fafc 48%, #f0fdf4 100%);
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 10px 28px rgba(34, 197, 94, 0.05);
}

.workspace-journal-intro {
  margin: 0;
  padding: 14px 16px 0;
  font-size: 13px;
  line-height: 1.45;
  color: #64748b;
}

.workspace-journal-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 10px 16px 12px;
}

.workspace-journal-filter {
  min-width: 132px;
  height: 30px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.45);
  background: rgba(255, 255, 255, 0.92);
  font: inherit;
  font-size: 13px;
}

.workspace-journal-count {
  font-size: 12px;
  color: #94a3b8;
}

.workspace-journal-list {
  list-style: none;
  margin: 0;
  padding: 12px 14px 16px;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  border-top: 1px solid rgba(148, 163, 184, 0.14);
  background:
    radial-gradient(ellipse 90% 70% at 12% 0%, rgba(34, 197, 94, 0.08), transparent 58%),
    radial-gradient(ellipse 80% 55% at 100% 100%, rgba(59, 130, 246, 0.06), transparent 52%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.55) 0%, rgba(241, 245, 249, 0.35) 100%);
}

.workspace-journal-item {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 12px 14px;
  align-items: start;
  padding: 13px 15px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 8px 20px rgba(15, 23, 42, 0.03);
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.15s ease;
}

.workspace-journal-item:hover {
  border-color: rgba(148, 163, 184, 0.38);
  box-shadow:
    0 2px 6px rgba(15, 23, 42, 0.05),
    0 10px 24px rgba(15, 23, 42, 0.05);
}

.workspace-journal-item-icon {
  margin-top: 2px;
}

.workspace-journal-item-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.workspace-journal-item.is-notify {
  border-color: rgba(59, 130, 246, 0.34);
  background: linear-gradient(135deg, rgba(239, 246, 255, 0.96) 0%, rgba(255, 255, 255, 0.94) 72%);
  box-shadow:
    inset 3px 0 0 rgba(59, 130, 246, 0.72),
    0 1px 2px rgba(15, 23, 42, 0.04);
}

.workspace-journal-item-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px 16px;
}

.workspace-journal-item-meta {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  min-width: 0;
}

.workspace-journal-item-author {
  font-size: 12px;
  color: #94a3b8;
}

.workspace-journal-item-author::before {
  content: "·";
  margin-right: 8px;
  color: #cbd5e1;
}

.workspace-journal-item-notify {
  font-size: 12px;
  line-height: 1;
}

.workspace-journal-item-time-col {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  text-align: right;
  white-space: nowrap;
}

.workspace-journal-item-time {
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
  font-variant-numeric: tabular-nums;
}

.workspace-journal-item-date {
  font-size: 11px;
  font-weight: 500;
  color: #94a3b8;
  text-transform: lowercase;
}

.workspace-journal-type-badge {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: lowercase;
  background: rgba(148, 163, 184, 0.16);
  color: #475569;
}

.workspace-journal-type-badge--life {
  background: rgba(244, 114, 182, 0.16);
  color: #be185d;
}

.workspace-journal-type-badge--action {
  background: rgba(59, 130, 246, 0.14);
  color: #1d4ed8;
}

.workspace-journal-type-badge--ui {
  background: rgba(34, 197, 94, 0.14);
  color: #15803d;
}

.workspace-journal-type-badge--system {
  background: rgba(100, 116, 139, 0.16);
  color: #334155;
}

.workspace-journal-item-body {
  white-space: pre-wrap;
  font-size: 14px;
  line-height: 1.58;
  color: #1e293b;
}

.workspace-journal-item-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding-top: 8px;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
}

.workspace-journal-item-path-row {
  margin-top: 8px;
  line-height: 1.4;
}

.workspace-journal-item-path {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-size: 12px;
  color: #2563eb;
  text-align: left;
  word-break: break-all;
  cursor: pointer;
}

.workspace-journal-item-path:hover {
  text-decoration: underline;
}

.workspace-journal-item-file {
  margin: 0;
  font-size: 11px;
  color: #94a3b8;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.workspace-journal-composer {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 12px 14px 14px;
  border-top: 1px solid rgba(148, 163, 184, 0.14);
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(10px);
}

.workspace-journal-composer-toolbar {
  display: grid;
  grid-template-columns: minmax(148px, auto) 1fr auto;
  align-items: center;
  gap: 10px 12px;
}

.workspace-journal-field {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.workspace-journal-field-label {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  color: #64748b;
  white-space: nowrap;
}

.workspace-journal-input {
  width: 100%;
  min-height: 3.25rem;
  max-height: 9rem;
  resize: vertical;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: #fff;
  font: inherit;
  font-size: 14px;
  line-height: 1.45;
  box-sizing: border-box;
}

.workspace-journal-type,
.workspace-journal-submit {
  height: 34px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.45);
  background: #fff;
  font: inherit;
  font-size: 13px;
  box-sizing: border-box;
}

.workspace-journal-type {
  min-width: 132px;
  max-width: 100%;
  flex: 1 1 auto;
  cursor: pointer;
  appearance: auto;
  -webkit-appearance: menulist;
}

.workspace-journal-submit {
  justify-self: end;
  border-color: rgba(34, 197, 94, 0.45);
  background: rgba(34, 197, 94, 0.12);
  color: #166534;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.workspace-journal-submit:disabled {
  opacity: 0.45;
  cursor: default;
}

.workspace-journal-notify {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  font-size: 13px;
  color: #475569;
  white-space: nowrap;
}

.workspace-journal-composer-hint {
  font-size: 12px;
  color: #94a3b8;
}

@media (max-width: 640px) {
  .workspace-journal-composer-toolbar {
    grid-template-columns: 1fr;
  }

  .workspace-journal-notify {
    justify-content: flex-start;
  }

